"""Cours et problèmes originaux de chimie organique pour PCSI et PC."""

from html import escape


def P(label, text):
    return "<p><b>" + escape(label) + "</b> " + escape(text) + "</p>"


def F(text):
    return "<div class='formula'>" + escape(text).replace("\n", "<br>") + "</div>"


def lesson(title, level, lab, *blocks):
    return dict(title=title, level=level, lab=lab, html="".join(blocks))


def exercise(title, level, lab, question, answer):
    return dict(title=title, level=level, lab=lab,
                question=P("Énoncé.", question), answer=P("Corrigé.", answer))


LESSONS = [
    lesson("1. Lewis : faire parler les électrons avant les noms", "Sup — PCSI", "electrons",
        P("Objets.", "Une formule de Lewis indique liaisons, doublets non liants et charges formelles. C, N et O de la deuxième période suivent normalement l’octet dans les espèces usuelles ; un carbocation possède un carbone déficient à six électrons. Un radical porte un électron célibataire. Le nombre d’électrons de valence total doit intégrer la charge globale."),
        F("qformel = V − Nnonliants − Nliaisons\nNélectrons = Σ Vatomes − charge globale (en unités e)\nC : V=4 ; N : V=5 ; O : V=6 ; H : V=1"),
        P("Calcul.", "Dans CH₃OH, l’oxygène possède deux liaisons et quatre électrons non liants : qO=6−4−2=0. Dans CH₃OH₂⁺, trois liaisons et un doublet donnent qO=6−2−3=+1. Dans CH₃O⁻, une liaison et trois doublets donnent qO=6−6−1=−1. La protonation modifie donc aussi la disponibilité d’un doublet et le caractère du groupe partant."),
        P("Exemple emblématique.", "Dans un groupe nitro R−N(O)₂, les formes usuelles sont R−N⁺(=O)−O⁻ et R−N⁺(−O⁻)=O. N porte quatre liaisons et aucune paire libre. Elles décrivent une seule espèce délocalisée ; ni un N pentavalent de deuxième période ni deux molécules en équilibre ne sont nécessaires."),
        P("Technique CPGE.", "Compter les électrons, compléter les octets, calculer chaque charge puis vérifier que leur somme est la charge globale. Une formule topologique omet les C et les H liés aux C, mais elle n’autorise pas à omettre une charge ou un H labile indispensable au mécanisme.")),
    lesson("2. Flèches courbes : une comptabilité qui construit le mécanisme", "Sup — PCSI", "electrons",
        P("Convention.", "Une flèche à deux pointes représente le déplacement d’un doublet. Son origine est un doublet ou une liaison ; sa pointe est un atome recevant la paire ou la liaison qui se forme. Une demi-flèche représente un électron dans un mécanisme radicalaire. Les flèches de réaction et de mésomérie ont d’autres rôles."),
        F("Nu:⁻ + C−X → Nu−C + X⁻\nB: + H−A → B−H⁺ + A⁻\nΣ charges et nombre de chaque atome conservés à chaque étape"),
        P("Dérivation.", "Pour HO⁻+CH₃Br→CH₃OH+Br⁻, une flèche part d’un doublet de O vers C, une seconde de la liaison C−Br vers Br. La charge initiale −1 se retrouve sur Br. Dans l’addition à un carbonyle, l’attaque du C impose en même temps le déplacement des électrons π vers O, sinon le C dépasserait l’octet."),
        P("Exemple.", "Protoner un alcool : le doublet de O pointe vers le H d’un acide, dont la liaison H−A pointe vers A. Le nouvel oxonium possède une charge +1 et peut libérer H₂O. Dessiner seulement H⁺ au-dessus d’une flèche globale est insuffisant pour expliquer l’activation microscopique."),
        P("Méthode.", "Après chaque étape, redessiner les doublets et recalculer les charges, sans déplacer les noyaux dans une simple forme mésomère. Les réactions concertées peuvent comporter plusieurs flèches simultanées ; cela ne crée pas automatiquement un intermédiaire isolable.")),
    lesson("3. Polarisation, effet inductif et polarisabilité", "Sup — PCSI", "electrons",
        P("Grandeurs.", "L’électronégativité χ compare l’attraction d’un atome pour les électrons d’une liaison. La charge partielle δ n’est pas une charge formelle entière. L’effet inductif se transmet par le squelette σ et diminue avec la distance. La polarisabilité mesure la déformation du nuage électronique et ne se confond pas avec χ."),
        F("χ(O)>χ(N)>χ(C)>χ(H) sur l’échelle de Pauling\nCδ+−Oδ− ; Cδ−−Mgδ+\nμinduit = α E ; α : polarisabilité"),
        P("Application.", "Dans un carbonyle, le C est électrophile ; dans un organomagnésien RMgX, le C lié à Mg est nucléophile et fortement basique. Un substituant CF₃ attire par effet −I ; les alkyles stabilisent souvent un carbocation par des interactions σ et hyperconjugaison. Le classement doit tenir compte aussi de la conjugaison."),
        P("Exemple.", "En eau, le pKa de l’acide chloroacétique est voisin de 2,9, celui de l’acide acétique de 4,8. Le Cl stabilise davantage le carboxylate par −I, donc favorise la dissociation. Pour comparer une série, conserver solvant et température ; les nombres sont ici des repères arrondis de lecture."),
        P("Technique.", "Séparer trois questions : où sont les sites polarisés, quel intermédiaire serait stabilisé, quelle réaction est réellement accessible ? Une flèche de dipôle ne donne ni une barrière d’activation ni une proportion de produits de synthèse.")),
    lesson("4. Mésomérie : stabilisation et sites de réaction", "Sup → PC", "electrons",
        P("Conditions.", "La conjugaison demande des orbitales p ou des doublets correctement orientés. Les formes mésomères conservent positions des noyaux, connectivité σ, charge globale et nombre d’électrons. Leur poids peut être différent : elles ne sont pas nécessairement équiprobables et ne s’interconvertissent pas comme des isomères."),
        F("CH₂=CH−CH₂⁺ ↔ ⁺CH₂−CH=CH₂\nR−CO−CH₂⁻ ↔ R−C(O⁻)=CH₂\n−OR et −NR₂ : donneurs +M ; −NO₂, −CN, −COR : attracteurs −M"),
        P("Enolate.", "L’énolate possède une charge distribuée entre O et le Cα. Il peut former une liaison C−C par attaque du C ou une liaison O−E par attaque de O. L’électrophile, le contre-ion, le solvant et la température interviennent : la seule forme au plus grand poids ne suffit pas à prédire toutes les sélectivités."),
        P("Exemple.", "Le doublet de l’azote d’une amide est délocalisé vers C=O : R−C(=O)−NH₂↔R−C(−O⁻)=NH₂⁺. Cela explique la faible basicité de l’azote, la planéité approximative et le caractère partiel de double liaison C−N. Le carbonyle d’amide est ainsi moins électrophile qu’un chlorure d’acyle."),
        P("Technique.", "Choisir d’abord le système conjugué, tracer une suite continue de flèches et distinguer stabilisation de réactif, d’intermédiaire et d’état de transition. Pour les halogènes aromatiques, −I et +M coexistent : désactivation et orientation ortho/para ne sont pas contradictoires.")),
    lesson("5. Acides et bases : comparer dans un même solvant", "Sup — PCSI", "acidebase",
        P("Cadre.", "HA est un acide de Brønsted et B une base ; leurs formes conjuguées sont A⁻ et BH⁺. Les pKa fournis pour calculer un équilibre doivent correspondre au même solvant, à la même température et à des états standards compatibles. En eau diluée, concentrations et activités sont assimilées dans le TP."),
        F("HA + B ⇌ A⁻ + BH⁺\nK ≈ 10^[pKa(BH⁺)−pKa(HA)]\n[A⁻]/[HA] = 10^(pH−pKa) ; fA⁻ = 1/[1+10^(pKa−pH)]"),
        P("Démonstration.", "Diviser Ka(HA) par Ka(BH⁺) fait disparaître l’activité du proton et donne K. Pour des réactifs équimolaires, sans produits initiaux et à volume constant, K=[x/(c₀−x)]² : la conversion est √K/(1+√K), distincte de K/(1+K) qui décrirait un rapport de deux formes à pH imposé."),
        P("Exemple.", "Acide acétique et NH₃ en eau : pKa=4,76 et 9,25, d’où K≈3,1×10⁴ et une conversion équimolaire ≈99,43 %. Un tampon acétate à pH=5,76 contient en revanche [A⁻]/[HA]=10 et 90,91 % de forme A⁻. Ces deux situations ne possèdent pas le même bilan."),
        P("Stratégie.", "Un carboxylique ou un alcool protonique détruit un organomagnésien par transfert de proton avant l’addition recherchée. Les pKa usuels de carbanions et d’énolates en solvants organiques sont fournis séparément ; on ne les soustrait pas à un pKa aqueux pour annoncer une constante précise.")),
    lesson("6. Nucléophile, base et groupe partant : trois rôles", "Sup → PC", "acidebase",
        P("Définitions.", "Un nucléophile fournit une paire à un électrophile pour former une liaison. Une base de Brønsted capte un proton. La basicité est reliée à un équilibre ; la nucléophilie se compare à des constantes de vitesse envers un substrat donné. Un groupe partant reçoit les électrons d’une liaison rompue."),
        F("Basicité : K d’un transfert de H⁺ ; nucléophilie : k d’une attaque\nAlcool ROH → oxonium ROH₂⁺ : départ de H₂O facilité\nI⁻, Br⁻, Cl⁻, sulfonates : groupes partants usuels ; HO⁻ : mauvais départ non activé"),
        P("Solvant.", "Un solvant protique peut solvater fortement un petit anion par liaisons hydrogène et ralentir son attaque. Dans un solvant polaire aprotique, la disponibilité d’un anion peut croître. Les effets de solvant sur ionisation, nucléophile, contre-ion et solubilité doivent être considérés ensemble."),
        P("Exemple.", "tert-BuO⁻ est une base forte encombrée : sur un halogénoalcane secondaire, l’élimination est souvent favorisée par rapport à une SN2. I⁻ peut être un bon nucléophile tout en étant une base faible. Dire « base forte donc bon nucléophile » ne résout pas cette comparaison."),
        P("Technique.", "Identifier les deux sites concurrents : C électrophile pour substitution, Hβ pour élimination. Justifier le choix avec classe du substrat, encombrement, qualité de départ, solvant et température. Le laboratoire compare des paramètres cinétiques annoncés, pas une table universelle de rendement.")),
    lesson("7. Configuration R/S : construire les priorités CIP", "Sup — PCSI", "stereo",
        P("Objets.", "Un centre tétraédrique portant quatre groupes différents est stéréogène. Pour CIP, classer les atomes directement liés par numéro atomique, puis comparer les listes d’atomes du premier rang différent dans l’ordre décroissant. Une liaison multiple se traite avec des atomes dupliqués dans cette règle."),
        F("Acide lactique CH₃−CH(OH)−CO₂H : OH > CO₂H > CH₃ > H\nPriorité 4 à l’arrière : 1→2→3 horaire = R, antihoraire = S\nee = |nR−nS|/(nR+nS) ; xmajoritaire = (1+ee)/2"),
        P("Pourquoi.", "Les groupes CO₂H et CH₃ commencent tous deux par C ; au rang suivant, le C carboxylique donne [O,O,O], le méthyle [H,H,H]. L’oxygène porte donc la première priorité, le carboxyle la deuxième. Tourner tout le modèle dans l’espace ne modifie pas R/S ; permuter deux groupes le modifie."),
        P("Exemple.", "Un mélange contenant 80 % R et 20 % S possède ee=60 %. Si, aux conditions données, l’énantiomère R pur a αpur=+12°, le mélange idéal donne α=+7,2°. Aucune règle ne relie R au signe + en général ; celui-ci est une propriété mesurée à longueur d’onde, température et solvant donnés."),
        P("Piège.", "L’inversion de Walden est géométrique. Si une réaction modifie aussi le classement CIP des substituants, l’étiquette R peut parfois rester R malgré l’inversion. Le TP affiche les priorités de son exemple ; il ne prétend pas attribuer CIP à toute molécule dessinée.")),
    lesson("8. E/Z, énantiomères et composés méso", "Sup — PCSI", "stereo",
        P("Double liaison.", "E/Z compare le groupe de priorité CIP la plus élevée sur chacun des deux C de C=C. E signifie côtés opposés, Z même côté. Chaque C doit porter deux substituants différents : le propène CH₂=CH−CH₃ ne possède pas de configuration E/Z."),
        F("E : priorités hautes opposées ; Z : priorités hautes du même côté\n2 centres distincts ⇒ au plus 2²=4 configurations\nAcide tartrique : (R,R), (S,S), et forme méso (R,S)≡(S,R)"),
        P("Chiralité.", "Des énantiomères sont images dans un miroir non superposables ; des diastéréoisomères ne sont pas cette paire miroir. Une molécule à centres stéréogènes peut être achirale si sa symétrie rend l’image miroir superposable. Le nombre 2ⁿ est une borne et doit être corrigé pour les symétries."),
        P("Exemple.", "Le but-2-ène E et Z est un couple de diastéréoisomères. Une bromation anti stéréospécifique de E-but-2-ène donne le 2,3-dibromobutane méso ; Z-but-2-ène donne un mélange racémique (R,R)/(S,S) dans un milieu achiral. Deux énantiomères comptent deux structures, même si une RMN en solvant achiral les superpose."),
        P("Technique.", "Dessiner les produits en trois dimensions avant de leur attribuer un nom. Distinguer stéréospécificité, qui relie des réactifs stéréoisomères à des produits distincts, et stéréosélectivité, qui favorise un stéréoisomère parmi les possibles.")),
    lesson("9. Newman et Boltzmann : les conformères ont une population", "Sup → PC", "conformeres",
        P("Angle.", "La projection de Newman regarde une liaison C−C suivant son axe. Pour le butane, θ désigne l’angle dièdre entre les deux groupes CH₃ : anti à 180°, gauche à ±60°, éclipsé à 0° ou ±120°. Une rotation autour d’une liaison σ change la conformation, pas la constitution ni normalement R/S."),
        F("pi = gi exp(−ΔGi/RT) / Σj gj exp(−ΔGj/RT)\nModèle discret : Ganti=0 ; Ggauche=3,8 kJ·mol⁻¹ ; ganti=1, ggauche=2\nÀ 298 K : Panti≈0,699 ; Pgauche,total≈0,301"),
        P("Calcul.", "RT≈2,478 kJ·mol⁻¹, donc exp(−3,8/RT)≈0,216. La fonction de partition réduite vaut 1+2×0,216=1,432. Le facteur 2 représente deux minima gauche, pas deux fois l’énergie. Les ΔG fournis dans ce modèle regroupent les corrections entropiques que l’on ignore dans une seule courbe torsionnelle d’énergie."),
        P("Lien réaction.", "Si seule une conformation rare est réactive, son taux de population peut diminuer la vitesse apparente. Cependant un produit majoritaire ne correspond pas nécessairement au conformère majoritaire : il faut aussi connaître les barrières d’attaque et la vitesse d’échange entre conformères."),
        P("Technique.", "Repérer minima et barrières, préciser si le calcul utilise une énergie ou une énergie libre, compter la dégénérescence. Une courbe continue de torsion et un modèle à trois minima ne définissent pas exactement la même moyenne statistique.")),
    lesson("10. Cyclohexane : chaises, axial/équatorial et E2", "Sup → PC", "conformeres",
        P("Géométrie.", "La chaise du cyclohexane évite l’éclipse des liaisons et maintient des angles proches du tétraèdre. Chaque C possède une liaison axiale et une équatoriale. Un basculement de chaise échange axial et équatorial tout en conservant le caractère haut/bas et donc cis/trans."),
        F("Méthylcyclohexane : ΔGax−eq≈7,5 kJ·mol⁻¹, valeur pédagogique\nPéquatorial = 1/[1+exp(−ΔGax−eq/RT)] ≈ 95,4 % à 298 K\nE2 dans une chaise : C−X axial et Cβ−H axial opposé"),
        P("Conformation.", "Un groupe axial subit des interactions 1,3-diaxiales ; un groupe volumineux favorise souvent la position équatoriale. Pour plusieurs substituants, on compare les contraintes simultanées des deux chaises. Le tert-butyle peut servir de verrou conformationnel approximatif."),
        P("Exemple.", "Pour trans-1-bromo-2-méthylcyclohexane, une chaise est diaxiale, l’autre diéquatoriale. La chaise réactive place Br axial mais CH₃ occupe le site axial voisin en C2 : il n’y a pas de H axial anti sur C2. L’élimination doit alors utiliser le H anti de C6, même si l’alcène obtenu est moins substitué."),
        P("Technique.", "Dessiner les Hβ plutôt que déduire le produit de la seule règle de Zaitsev. Les règles de stabilité donnent une tendance entre voies permises ; la contrainte stéréoelectronique peut supprimer la voie qui serait autrement préférée.")),
    lesson("11. Formule brute, insaturation et spectrométrie de masse", "Sup → PC", "formule",
        P("Cadre.", "L’indice d’insaturation IHD s’applique aux formules neutres usuelles à valences C4, N3, H1 et halogènes X1. O et S divalents n’interviennent pas dans cette expression. La masse moyenne molaire et la masse exacte monoisotopique sont deux grandeurs différentes ; m/z dépend de l’ion observé et de sa charge."),
        F("IHD = (2C+2+N−H−X)/2\ncycle : 1 ; C=C ou C=O : 1 ; C≡C : 2\n1 Cl : M:M+2≈3:1 ; 1 Br : M:M+2≈1:1"),
        P("Exemple.", "C₈H₈O₂ donne IHD=(16+2−8)/2=5. Un noyau benzénique en consomme quatre, un carbonyle un : cela admet l’acide phénylacétique, le benzoate de méthyle et d’autres isomères. La formule seule ne les départage pas. C₆H₅Br donne IHD=4 en remplaçant le Br par un H dans le comptage."),
        P("Isotopes.", "Pour deux Cl, le développement (3+x)² donne une enveloppe approximative 9:6:1 aux masses M,M+2,M+4. Pour deux Br, (1+x)² donne 1:2:1. Les proportions réelles dépendent des abondances naturelles et de la superposition avec ¹³C ; le TP sépare cette enveloppe pédagogique des fragments chimiques."),
        P("Technique.", "Identifier d’abord M⁺·, [M+H]⁺ ou un autre ion selon l’ionisation, puis vérifier l’IHD entier et non négatif, les atomes et la cohérence de toutes les données. Un pic intense n’est pas automatiquement l’ion moléculaire.")),
    lesson("12. Infrarouge : des vibrations au diagnostic fonctionnel", "Sup — PCSI option PC", "ir",
        P("Grandeurs.", "Le nombre d’onde ṽ est en cm⁻¹ ; une fréquence s’obtient par ν=cṽ avec c exprimé en cm·s⁻¹. Un mode IR actif fait varier le moment dipolaire. La transmittance T=I/I₀ est une fraction ; l’absorbance A=−log₁₀T s’additionne pour les espèces indépendantes."),
        F("ṽ = [1/(2πc)]√(k/μ) ; μ=m₁m₂/(m₁+m₂)\nA=εℓc ; T=10^(−A)\nC=O souvent 1650–1800 cm⁻¹ ; OH lié : bande large souvent 3200–3600 cm⁻¹"),
        P("Dérivation.", "Dans un modèle à deux masses et ressort, la coordonnée relative obéit à μq″+kq=0. Une liaison plus raide élève la fréquence ; une masse réduite plus grande l’abaisse. La conjugaison réduit souvent le caractère local de double liaison C=O et son nombre d’onde, sans que cela constitue une loi indépendante du groupe fonctionnel."),
        P("Exemple.", "Passer de OH à OD à constante k égale donne ṽOD/ṽOH≈√(μOH/μOD)≈0,728. Une bande OH à 3400 cm⁻¹ devient vers 2475 cm⁻¹ dans cette approximation. A=0,30 correspond à T≈0,501 ; doubler la concentration donne A=0,60 et T≈0,251, pas la moitié de 0,501."),
        P("Diagnostic.", "Comparer présence et absence de OH, C=O, NH et CN, puis la région d’empreinte. Les courbes du TP sont des bandes pédagogiques calculées ; une identification expérimentale demande un spectre mesuré et ses conditions, comme les références institutionnelles NIST.")),
    lesson("13. RMN du proton : déplacements, intégrales et couplages", "Sup — PCSI option PC", "rmn",
        P("Grandeurs.", "Le déplacement chimique δ=(ν−νréf)/ν₀×10⁶ est en ppm ; J est une constante de couplage en Hz. Les intégrales de massifs, acquises quantitativement, sont proportionnelles au nombre de noyaux. Des protons chimiquement et magnétiquement équivalents ne se dédoublent pas entre eux dans le modèle usuel."),
        F("Δν en Hz = Δδ en ppm × ν₀ en MHz\nPremier ordre : Δν/J ≫ 1\nn voisins équivalents spin 1/2 ⇒ n+1 raies, intensités binomiales"),
        P("Exemple.", "Pour CH₃COOCH₂CH₃, on attend approximativement un singulet 3H vers 2,0 ppm, un quartet 2H vers 4,1 ppm et un triplet 3H vers 1,25 ppm. Le groupe éthyle possède le même J≈7 Hz dans ses deux massifs. À 400 MHz, 7 Hz correspondent à 0,0175 ppm : le couplage ne devient pas 7 ppm."),
        P("Limites.", "Deux déplacements séparés de 0,02 ppm à 60 MHz donnent Δν=1,2 Hz : pour J=7 Hz, le premier ordre échoue. À 600 MHz, Δν=12 Hz reste comparable à J. Une augmentation du champ améliore souvent la séparation mais ne garantit pas que toute molécule devienne AX."),
        P("Technique.", "Lier chaque intégrale à un nombre d’H, chaque J à une connectivité et chaque δ à un environnement. OH/NH peuvent échanger et ne suivent pas toujours n+1. Le ¹³C découplé fournit un nombre d’environnements ; ses hauteurs ne sont pas généralement des intégrales quantitatives du nombre de C.")),
    lesson("14. Résoudre une structure par plusieurs données indépendantes", "Sup → PC", "ir",
        P("Méthode.", "Une caractérisation convaincante croise formule brute, insaturation, IR, RMN et contexte de synthèse. Chaque mesure élimine des structures ; aucune signature isolée ne doit remplacer le bilan complet. UV-visible renseigne notamment sur des transitions électroniques et sur une conjugaison, mais n’attribue pas seul la connectivité."),
        F("C₄H₈O₂ : IHD=1 ; M≈88,1 g·mol⁻¹\nIR C=O d’ester + RMN 3H s / 2H q / 3H t ⇒ CH₃COOCH₂CH₃\nEtransition=hc/λ ; λ=300 nm ⇒ E≈4,13 eV"),
        P("Raisonnement.", "L’IHD=1 autorise carbonyle, cycle ou alcène. L’IR d’ester retient un carbonyle et un lien C−O. La paire quartet/triplet 2H/3H place un groupe éthyle ; son CH₂ vers 4 ppm indique O−CH₂. Le singulet restant 3H se place sur CO−CH₃. Le propanoate de méthyle aurait un OCH₃ singulet et un CH₂ plus proche de 2,3 ppm."),
        P("Sélectivité.", "Réduire une cétone insaturée peut modifier C=O seul ou aussi C=C selon le réducteur. Disparition du C=O en IR, apparition de CH−OH et maintien des protons vinyliques en RMN justifient une réduction 1,2 chimiosélective ; la disparition d’une tache de CCM ne suffit pas à l’établir."),
        P("Au-delà guidé.", "COSY recherche des corrélations de couplage, HSQC des corrélations ¹H−¹³C à une liaison, HMBC à plus longue distance. Ce sont des extensions introduites avec leurs règles ; leur connaissance n’est pas supposée pour les exercices de base.")),
    lesson("15. CCM : voir une séparation, suivre une transformation", "Sup — TP PCSI", "ccm",
        P("Montage.", "Sur silice en phase normale, la phase stationnaire est polaire. Rf est le rapport distance centre de tache/distance front depuis la même ligne de dépôt. Il dépend de la plaque, de l’éluant, de la charge déposée et des conditions. Une valeur n’est pas une constante d’identité absolue."),
        F("Rf = dsubstance/dfront ; 0≤Rf≤1\nRf≈1/(1+k′) dans un modèle de rétention simplifié\nRésolution qualitative : comparer ΔRf aux largeurs des taches"),
        P("Solvant.", "Augmenter la force éluante en phase normale diminue souvent la rétention sur silice et élève les Rf. Si toutes les taches restent au dépôt ou courent avec le front, la séparation est peu informative. Les gradients du laboratoire simulent une réponse explicitement paramétrée, pas un calcul ab initio d’adsorption."),
        P("Exemple.", "Front à 60 mm et tache à 24 mm donnent Rf=0,40. Deux taches à 24 et 27 mm, chacune large de 5 mm, ne sont pas nettement séparées. Une co-tache référence+produit est utile, mais deux molécules différentes peuvent migrer ensemble dans un éluant donné."),
        P("TP.", "Prélever une aliquote, arrêter ou diluer sa réaction si nécessaire, déposer peu, comparer réactif et produit avec des références. L’intensité révélée peut varier avec le chromophore et la révélation : elle n’est pas automatiquement un rendement ni une concentration étalonnée.")),
    lesson("16. Extraction : séparer par partage et par pH", "Sup — TP PCSI", "extraction",
        P("Définitions.", "P=[S]org/[S]aq désigne le partage de la forme neutre à l’équilibre. D est le rapport des concentrations totales dans les deux phases. Pour un acide faible, la forme ionisée reste supposée aqueuse ; un pH maintenu par tampon fixe la fraction neutre. Volumes en mL doivent être employés de façon cohérente dans les rapports."),
        F("Acide HA : D=P/[1+10^(pH−pKa)]\nBase B : D=P/[1+10^(pKa(BH⁺)−pH)]\nFraction aqueuse après n extractions : q=[Vaq/(Vaq+D Vorg/n)]ⁿ"),
        P("Démonstration.", "Une conservation n₀=CaqVaq+CorgVorg et Corg=DCaq donne q=Vaq/(Vaq+DVorg). Répéter avec du solvant neuf multiplie les fractions résiduelles. L’expression n suppose des contacts indépendants, équilibre atteint, volumes constants et absence de dégradation ou d’émulsion."),
        P("Exemple.", "Avec D=5, Vaq=100 mL et 100 mL de solvant total, une extraction laisse 1/6=16,7 % ; deux de 50 mL laissent (1/3,5)²=8,16 %. Un acide de pKa=4,5 et P=10 à pH=6,5 a D≈0,099 : il demeure principalement aqueux. À pH=2,5, D≈9,90."),
        P("Technique.", "Identifier la phase supérieure par la densité mesurée ou fournie, pas par le mot organique. Une extraction acido-basique transforme une espèce pour modifier D, puis peut la régénérer. Le modèle à pH imposé doit être complété par un bilan de protons si le milieu n’est pas tamponné.")),
    lesson("17. SN2 : attaque arrière et cinétique bimoléculaire", "Sup — PCSI", "sn2",
        P("Mécanisme.", "Nu attaque le C porteur du groupe partant du côté opposé à C−X. Formation C−Nu et rupture C−X sont concertées ; l’état de transition n’est pas un carbocation. La trajectoire met en jeu le recouvrement du doublet nucléophile avec l’orbitale antiliante σ* C−X."),
        F("v=k₂[RX][Nu] ; k₂ en L·mol⁻¹·s⁻¹\nNu en grand excès : [RX](t)≈[RX]₀ exp(−k₂[Nu]₀t)\nInversion géométrique au centre réactif (Walden)"),
        P("Exemple.", "Avec k₂=0,20 L·mol⁻¹·s⁻¹ et [Nu]₀=0,50 mol·L⁻¹ maintenu presque constant, kobs=0,10 s⁻¹ et t₁/₂=6,93 s. Doubler [Nu] divise ce temps par deux. L’approximation doit être vérifiée en comparant [RX]₀ à [Nu]₀, et ne découle pas du seul nom SN2."),
        P("Réactivité.", "Méthyle et C primaires peu encombrés sont favorables ; un C tertiaire est inaccessible à la SN2 usuelle. Un groupe néopentyle est primaire mais fortement gêné au voisinage. Un carbone sp² d’halogénure aryle ou vinylique ne suit pas cette attaque SN2 alkyle ordinaire."),
        P("Application.", "La synthèse de Williamson forme un éther par RO⁻+R′X→ROR′+X⁻. Placer le groupe alkyle le moins encombré sur R′X limite E2 ; utiliser un halogénure tertiaire pour préparer un éther très encombré par cette route conduit surtout à une élimination.")),
    lesson("18. SN1 : ioniser, piéger et parfois réarranger", "Sup — PCSI", "sn1",
        P("Étapes.", "Dans le schéma limite, une ionisation lente RX→R⁺+X⁻ précède une attaque rapide puis, si Nu est neutre, une déprotonation. Les carbocations allyliques, benzyliques et tertiaires sont souvent mieux stabilisés que des primaires. Un solvant ionisant facilite la séparation des charges."),
        F("Si ionisation irréversible déterminante : v=k₁[RX]\n[RX](t)=[RX]₀exp(−k₁t) ; t₁/₂=ln2/k₁\nCarbocation plan : deux faces accessibles ; paire d’ions possible"),
        P("Stéréochimie.", "Un carbocation libre plan, attaqué de façon symétrique en milieu achiral, donne un racémique lorsqu’un seul nouveau centre est formé. Une paire d’ions ou un environnement chiral peut différencier les faces. La perte de configuration n’impose donc pas une proportion 50/50 pour chaque solvolyse réelle."),
        P("Exemple.", "Pour k₁=0,015 s⁻¹, t₁/₂≈46,2 s et la fraction restante à 120 s vaut exp(−1,8)≈16,5 %. Ajouter un nucléophile peut modifier la capture et la distribution de produits sans modifier la vitesse limite d’ionisation ; des mécanismes concurrents peuvent cependant changer la loi observée."),
        P("Technique.", "Séparer la formation du carbocation de sa capture, examiner une migration d’hydrure ou d’alkyle vers un cation plus stable, et confronter vitesse, produits et stéréochimie. Une loi de premier ordre constitue un indice, pas la preuve unique d’un mécanisme.")),
    lesson("19. Compétition substitution/élimination : les vitesses sélectionnent", "Sup → PC", "competition",
        P("Modèle.", "Quatre issues consomment un même substrat S : SN1, E1, SN2, E2. L’ionisation peut être commune à SN1/E1 : on compte alors une seule vitesse d’ionisation, répartie ensuite entre capture et élimination. En conditions pseudo-premier ordre et sans interconversion des produits, les taux apparents λi de chemins indépendants s’additionnent. Le laboratoire règle des constantes déclarées ; une dépendance en température est étudiée dans le laboratoire Cinétique."),
        F("d[S]/dt=−(Σλi)[S] ; Pi(t)=[S]₀ λi/(Σλi)[1−exp(−Σλi t)]\nFraction du produit i = λi/Σλi\nk=A exp(−Ea/RT) ; A porte les unités de k"),
        P("Exemple.", "Si λSN2=0,06 s⁻¹ et λE2=0,02 s⁻¹, la sélectivité de substitution vaut 75 %, quelle que soit la conversion dans ce modèle. À t=20 s, la conversion est 1−exp(−1,6)=79,8 %, mais la quantité de produit SN2 représente 59,9 % du substrat initial. Conversion et sélectivité ne sont pas interchangeables."),
        P("Règles contextualisées.", "Un nucléophile peu encombré sur un primaire favorise souvent SN2 ; une base encombrée et un substrat secondaire/tertiaire favorisent E2 ; un substrat pouvant ioniser ouvre SN1/E1. Chauffer peut favoriser certaines éliminations, mais une conclusion quantitative exige les paramètres d’activation ou des mesures."),
        P("Technique.", "Déterminer l’ordre expérimental, proposer les voies compatibles, écrire leurs produits et tester le bilan de matière. Un modèle de chemins parallèles est une étude contrôlée de causalité ; ses pourcentages ne sont pas des rendements prédits pour tout réactif commercial.")),
    lesson("20. E2 : trois mouvements concertés et une géométrie anti", "Sup — PCSI", "elimination",
        P("Étape.", "Une base arrache Hβ, les électrons Cβ−H forment Cα=Cβ et la liaison Cα−X se rompt vers X. Les trois mouvements sont simultanés. Le recouvrement orbital est favorable lorsque Cβ−H et Cα−X sont anti-périplanaires ; syn peut être imposé dans certains systèmes particuliers."),
        F("v=kE2[RX][B] ; Δdièdre(Hβ−Cβ−Cα−X)≈180°\nBase peu encombrée : tendance Zaitsev si les voies sont permises\nBase encombrée : produit moins substitué parfois favorisé (Hofmann)"),
        P("Exemple.", "Le 2-bromobutane peut produire but-1-ène et E/Z-but-2-ène. Des conformations anti différentes donnent les différents alcènes ; E-but-2-ène est souvent favorisé avec une petite base. Une population de conformères et des barrières distinctes sont nécessaires pour chiffrer les proportions."),
        P("Stéréospécificité.", "Sur une chaîne portant deux centres, choisir le H anti impose une configuration de l’alcène. Sur cyclohexane, l’exigence devient trans-diaxiale et peut contredire une simple prévision de stabilité. Les atomes H implicitement omis doivent être réintroduits dans le dessin."),
        P("Technique.", "Repérer tous les Cβ possédant un H, construire les Newman ou les chaises, éliminer les voies géométriquement interdites, puis comparer les voies restantes. Un alcène sans substituants différents sur chacun des C ne reçoit pas de descripteur E/Z.")),
    lesson("21. E1 et déshydratation : stabilité et catalyse acide", "Sup → PC", "elimination",
        P("Étapes.", "Pour un alcool pouvant former un cation stabilisé, protonation de OH facilite le départ de H₂O, puis une base enlève Hβ et donne l’alcène. Le proton est régénéré : l’acide est catalyseur. Un alcool primaire suit souvent une élimination concertée en milieu acide plutôt qu’un carbocation primaire libre."),
        F("ROH + H⁺ ⇌ ROH₂⁺ → R⁺ + H₂O → alcène + H⁺\nE1 et SN1 peuvent partager un intermédiaire\nUn catalyseur abaisse les barrières et ne change pas K à température fixée"),
        P("Réarrangement.", "Une migration de H⁻ ou d’un groupe alkyle au sein du cation peut déplacer le site de charge et donc le squelette du produit. Elle doit être écrite avant l’élimination ou la capture. Le mécanisme E2, sans cation libre, ne permet pas cette même migration intermédiaire."),
        P("Exemple.", "La déshydratation de 2-méthylbutan-2-ol donne notamment 2-méthylbut-2-ène et 2-méthylbut-1-ène. Le plus substitué est souvent favorisé dans ces conditions, mais retirer l’eau, la température et les équilibres entre alcènes peuvent changer le résultat final."),
        P("Technique.", "Écrire l’activation et les transferts de protons, vérifier la régénération du catalyseur et distinguer vitesse de formation et composition à l’équilibre. Une règle de stabilité sans mécanisme ne permet pas de prédire un squelette réarrangé.")),
    lesson("22. Profils d’énergie : contrôle cinétique et thermodynamique", "Sup option PC → PC", "cinetique",
        P("Conventions.", "Un profil G(q) utilise une coordonnée réactionnelle abstraite q, distincte du temps. Un maximum est un état de transition, un minimum interne un intermédiaire. ΔG° compare produits et réactifs ; ΔG‡ compare l’état de transition au réactif de l’étape. Toutes les énergies libres sont ici molaires en kJ·mol⁻¹."),
        F("K=exp(−ΔG°/RT)\nk≈κ(kBT/h)exp(−ΔG‡/RT), forme d’Eyring (prolongement)\nRapport cinétique kA/kB≈exp[−(ΔG‡A−ΔG‡B)/RT] si préfacteurs comparables"),
        P("Exemple.", "À 298 K, un produit A accessible par une barrière plus basse de 5,0 kJ·mol⁻¹ se forme environ 7,5 fois plus vite que B si les préfacteurs sont égaux. Si B est plus stable de 8,0 kJ·mol⁻¹, l’équilibre favorise pourtant B/A≈25. Il faut une possibilité de réversibilité et un temps suffisant pour atteindre cet équilibre."),
        P("Intermédiaires.", "Dans S→I→P, une faible accumulation de I peut permettre l’approximation d’état quasi stationnaire d[I]/dt≈0, après un régime initial. L’étape dont la barrière locale est la plus élevée n’est pas automatiquement la déterminante globale si le réactif de cette étape est très rare."),
        P("Technique.", "Dessiner un bilan énergétique cohérent avec le mécanisme, comparer barrières et profondeurs, choisir un observable temporel puis tester conservation et réversibilité. Les animations ne font pas traverser une barrière à une molécule comme un wagon mécanique.")),
    lesson("23. Alcènes : orientation, bromonium et hydroboration", "PC ; premières lectures accompagnées en Sup", "alcene",
        P("Rôles.", "La liaison π d’un alcène est nucléophile. HBr ionique ou une hydratation acide commence par protonation et formation d’un cation ; l’orientation favorise souvent le cation le mieux stabilisé. Une bromation Br₂ passe usuellement par un bromonium ponté, puis une attaque arrière et une addition anti."),
        F("Propène + HBr (voie ionique) → majoritairement 2-bromopropane\n1) BH₃ ou borane adapté ; 2) H₂O₂, HO⁻ ⇒ alcool anti-Markovnikov, addition H/OH syn\nBr₂ : addition anti ; H₂/catalyseur : addition syn"),
        P("Hydroboration.", "H et B s’ajoutent dans une étape concertée, B préférant généralement le C le moins substitué. L’oxydation remplace C−B par C−O avec conservation de la disposition au C concerné. Le bilan syn compare le H ajouté et OH final ; il ne s’agit pas d’une dihydroxylation syn, qui ajoute deux OH."),
        P("Exemple.", "Le propène donne propan-2-ol par hydratation acide mais propan-1-ol par hydroboration/oxydation. Le but-2-ène E bromé donne un méso, son isomère Z une paire racémique. Pour un alcène trisubstitué, vérifier simultanément orientation et création éventuelle d’un centre chiral."),
        P("Technique.", "Annoncer réactifs, étapes et intermédiaires avant de citer Markovnikov. Une règle d’orientation ne détermine pas la stéréochimie ; des conditions radicalaires ou concertées changent le mécanisme et peuvent changer l’orientation.")),
    lesson("24. Chaînes radicalaires : HBr sous conditions dédiées", "PC ; prolongement mécanistique accompagné", "radical",
        P("Étapes.", "Initiation forme des radicaux, propagation consomme un réactif en régénérant un radical, terminaison couple deux radicaux. En présence d’une source radicalaire adaptée, Br· peut s’additionner au propène de façon à former le radical carboné secondaire, puis celui-ci arrache H à HBr."),
        F("Br· + CH₂=CHCH₃ → BrCH₂−CH·−CH₃\nBrCH₂−CH·−CH₃ + HBr → BrCH₂CH₂CH₃ + Br·\nBilan : HBr + propène → 1-bromopropane"),
        P("Orientation.", "Elle résulte de la stabilité du radical et de la cinétique des deux étapes de propagation, sans carbocation. Le même raisonnement ne s’étend pas automatiquement à HCl et HI : les bilans énergétiques des étapes peuvent interrompre une chaîne efficace."),
        P("Modèle cinétique.", "Si Ri est une vitesse d’initiation en mol·L⁻¹·s⁻¹ et kt une constante de terminaison en L·mol⁻¹·s⁻¹, l’état quasi stationnaire donne une concentration radicalaire de l’ordre de √(Ri/(2kt)), selon la convention de comptage de Ri. Une propagation de vitesse kp[alcène][radical] augmente alors comme √Ri."),
        P("Technique.", "Repérer l’électron célibataire à chaque étape, utiliser des demi-flèches, vérifier la régénération du porteur de chaîne et son bilan net. Les courbes du TP explorent un schéma radicalaire simplifié ; elles n’ajoutent pas une chaîne en l’absence des conditions d’initiation.")),
    lesson("25. Alcynes : arrêter la réduction et lire la tautomérie", "PC — banque de transformations du recueil", "alcyne",
        P("Réactivité.", "Une triple liaison compte deux unités d’insaturation et peut subir deux additions successives. La réduction totale par H₂ sur catalyseur adapté donne l’alcane ; une réduction partielle exige un réactif et des conditions spécifiques. Un alcyne terminal possède aussi un H relativement acide pour une liaison C−H."),
        F("Alcyne interne + H₂/Lindlar ⇒ alcène Z (syn)\nMétal dissous, conditions adaptées ⇒ alcène E (anti globale)\nAlcyne terminal + H₂O/H⁺/Hg²⁺ ⇒ énol puis méthylcétone, sauf acétylène"),
        P("Tautomérie.", "Un énol et un carbonyle sont des tautomères, donc des espèces distinctes reliées par transfert de proton et déplacement de liaison π. Ce ne sont pas des formes mésomères. L’hydratation du prop-1-yne forme CH₃−C(OH)=CH₂ puis propanone ; celle de l’acétylène forme l’éthanal."),
        P("Exemple.", "But-2-yne : une équivalence d’H₂ sous Lindlar permet Z-but-2-ène ; une réduction par métal dissous permet E-but-2-ène ; H₂ en excès sur un catalyseur non sélectif donne butane. L’hydroboration/oxydation adaptée d’un alcyne terminal conduit plutôt à un aldéhyde."),
        P("Technique.", "Distinguer une équivalence stœchiométrique de la capacité du catalyseur à arrêter la réaction. Dessiner d’abord l’énol puis le carbonyle, conserver le squelette C et vérifier si E/Z est défini. Le détail opératoire de ces banques n’est pas exigé sans données fournies.")),
    lesson("26. Addition nucléophile aux carbonyles : ouvrir π puis protoner", "Sup — PCSI", "carbonyle",
        P("Site.", "Dans C=O, le C est électrophile et O donneur de doublets. L’attaque d’un nucléophile sur le C déplace les électrons π vers O et donne un intermédiaire tétraédrique. Un aldéhyde est généralement moins encombré et plus électrophile qu’une cétone comparable ; substituants et conjugaison nuancent cette tendance."),
        F("R₂C=O + Nu⁻ → R₂C(O⁻)Nu → après protonation R₂C(OH)Nu\nNaBH₄ : transfert d’hydrure puis hydrolyse/protonation ⇒ alcool\nCarbonyle plan : faces Re/Si, souvent deux voies en milieu achiral"),
        P("Exemple.", "L’hydrure ajouté à propanone donne un alcoolate puis propan-2-ol, sans création de centre chiral. L’ajout à butan-2-one donne butan-2-ol avec deux énantiomères si aucune influence chirale ne différencie les faces. Le doublet nucléophile n’est pas dessiné comme H⁺."),
        P("Milieu acide.", "Une protonation de O active le carbonyle envers un nucléophile neutre, comme un alcool. Mais un nucléophile fortement basique est détruit par l’acide ; il faut choisir une séquence compatible. Une même étape formelle « addition » ne se réalise pas par les mêmes conditions pour tous les Nu."),
        P("Technique.", "Compter les nouvelles liaisons C−C ou C−H et les charges, puis distinguer l’addition à un aldéhyde/cétone de la substitution sur un dérivé d’acide possédant un groupe éliminable. L’étape finale de traitement aqueux doit apparaître dans le bilan.")),
    lesson("27. Organomagnésiens : créer une liaison C−C avec un bilan exact", "Sup — PCSI", "grignard",
        P("Préparation.", "RMgX est obtenu à partir de RX et Mg en milieu éthéré anhydre adapté. L’éther coordonne Mg ; eau, alcools, acides et autres protons labiles consomment le réactif. La formule RMgX est un modèle utile d’espèces agrégées et solvatées, pas un carbanion libre isolé en solution."),
        F("RMgX + R′₂C=O → R′₂C(OMgX)R ; puis H₃O⁺ → R′₂C(OH)R\nRMgX + CO₂ → RCO₂MgX ; puis H₃O⁺ → RCO₂H\nRMgX + H−A → RH + sels de Mg"),
        P("Classe d’alcool.", "Méthanal donne un alcool primaire, un autre aldéhyde un secondaire, une cétone un tertiaire. Le carbone du carbonyle reste dans le produit : CO₂ ajoute un C au squelette de R. Une synthèse rétrograde d’un alcool doit explorer les coupures possibles autour du C portant OH."),
        P("Exemple.", "PhMgBr et éthanal donnent 1-phényléthanol après hydrolyse. PhMgBr et CO₂ donnent l’acide benzoïque. Un ester R′COOR″ consomme normalement deux équivalents de RMgX et donne R′C(OH)R₂ : le premier alcoolate intermédiaire élimine OR″ puis la cétone formée réagit encore."),
        P("Technique TP.", "Justifier anhydrie, solvant, ordre d’addition, gestion du réactif limitant et hydrolyse terminale. L’absence d’eau n’est pas une décoration du protocole ; elle détermine quelle réaction gagne. Un modèle de compatibilité est plus instructif qu’un rendement fictif arbitraire.")),
    lesson("28. Époxydes : ouvrir un cycle pour allonger une chaîne", "PC — extension fournie à partir des organomagnésiens", "grignard",
        P("Tension et sites.", "Un époxyde possède un cycle à trois atomes C−C−O. Sa tension favorise l’ouverture. En conditions nucléophiles basiques, l’attaque ressemble à une SN2 au C le moins encombré et rompt sa liaison C−O. Une activation acide modifie la polarisation et l’orientation possible."),
        F("RMgX + oxirane → R−CH₂−CH₂−OMgX ; puis H₃O⁺ → R−CH₂−CH₂OH\nOuverture nucléophile : attaque arrière, inversion au C attaqué\nOuverture acide d’un époxyde dissymétrique : orientation à discuter avec les conditions"),
        P("Exemple.", "CH₃MgBr et oxirane donnent propan-1-ol après hydrolyse : deux C proviennent du cycle et un du nucléophile. Avec un époxyde substitué, redessiner le produit avant d’annoncer OH : l’oxygène demeure lié au C qui n’a pas été attaqué."),
        P("Synthèse du cycle.", "L’époxydation d’un alcène par un peracide est concertée et conserve les positions relatives des substituants. Une ouverture anti ultérieure peut construire un diol trans. Les étapes de formation et d’ouverture possèdent donc des exigences stéréochimiques différentes."),
        P("Technique.", "Nommer le C attaqué, tracer simultanément attaque et rupture C−O, conserver les atomes et appliquer l’hydrolyse. L’extension du squelette doit être comptée avant la recherche de la fonction finale ; sinon une route peut donner le mauvais nombre de C.")),
    lesson("29. Oxydoréduction : niveaux d’oxydation et chimiosélectivité", "Sup — PCSI option PC ; approfondissement PC", "oxydoreduction",
        P("Comptage.", "Pour attribuer le nombre d’oxydation d’un C, partager C−C à égalité, attribuer C−H au C et C−O/C−N/C−X au partenaire plus électronégatif. Une oxydation organique augmente ce nombre ; elle n’exige pas que des électrons libres apparaissent dans le mécanisme moléculaire."),
        F("RCH₂OH → RCHO + 2 H⁺ + 2 e⁻\nRCHO + H₂O → RCO₂H + 2 H⁺ + 2 e⁻\nR₂CHOH → R₂CO + 2 H⁺ + 2 e⁻"),
        P("Sélectivité.", "Une oxydation douce contrôlée d’un primaire peut s’arrêter à l’aldéhyde ; eau, oxydant et conditions peuvent conduire à l’acide. Un tertiaire n’a pas de H sur le C portant OH : l’oxydation en carbonyle avec squelette conservé est indisponible, tandis qu’une oxydation très forte peut casser des liaisons C−C."),
        P("Exemple.", "NaBH₄ réduit normalement aldéhydes et cétones dans les conditions usuelles de cours sans réduire un ester simple. LiAlH₄ peut réduire aussi esters et acides, avec des conditions distinctes et une incompatibilité avec les milieux protiques. Réduire une cétone en présence d’un ester est donc un problème de choix de réactif et de vérification IR/RMN."),
        P("Aniline.", "La demi-équation de réduction du nitrobenzène est PhNO₂+6H⁺+6e⁻→PhNH₂+2H₂O. Si le produit réel en milieu acide est anilinium, ajouter sa protonation. Pour un métal oxydé, équilibrer l’autre demi-équation avant de calculer réactif limitant et rendement."),
        P("Ester : approfondissement PC.", "Un hydrure attaque RCOOR′, l’intermédiaire tétraédrique élimine OR′ et donne un aldéhyde RCHO ; une seconde attaque donne RCH₂O⁻ puis RCH₂OH au traitement final. LiAlH₄ réalise usuellement cette réduction totale. Arrêter à l’aldéhyde demande un réducteur et des conditions spécifiques fournis, par exemple DIBAL-H à basse température avec une stœchiométrie et une hydrolyse adaptées. Le sous-produit R′OH est également récupéré après traitement ; ses atomes ne disparaissent pas.")),
    lesson("30. Estérification, hydrolyse et saponification", "Sup → PC ; TP", "esterification",
        P("Systèmes.", "L’estérification acide-alcool et l’hydrolyse acide sont réversibles. La catalyse acide accélère l’approche de l’équilibre dans les deux sens. La saponification basique forme un carboxylate : sa stabilisation acido-basique rend généralement la transformation pratiquement complète dans les conditions étudiées."),
        F("RCO₂H + R′OH ⇌ RCO₂R′ + H₂O\nK=aester aeau/(aacide aalcool)\nRCO₂R′ + HO⁻ → RCO₂⁻ + R′OH"),
        P("Modèle de TP.", "Pour un mélange homogène idéal contenant une mole d’acide, une mole d’alcool et aucune eau/ester initial, K=x²/(1−x)². K=4 donne x=2/3. Ajouter de l’alcool ou retirer de l’eau peut déplacer l’équilibre. Si l’eau est le solvant majoritaire, son activité proche de 1 ne se traite pas comme celle du même mélange équimolaire."),
        P("Mécanisme.", "Une addition au carbonyle suivie d’une élimination et de transferts de proton décrit une substitution nucléophile d’acyle. Un milieu acide rend possible le départ d’une molécule neutre ; en milieu basique, l’étape finale de protonation du carboxylate nécessite un traitement acidifiant distinct."),
        P("Technique.", "Un montage à reflux accélère la réaction sans confondre durée et équilibre. Pour une synthèse d’acétate ou d’aspirine, calculer rendement isolé après purification, vérifier identité et pureté par plusieurs mesures ; une masse de produit encore humide ne mesure pas le rendement fiable."),
        P("Hydrolyse d’amide : PC.", "RCONHR′+H₂O donne RCO₂H+R′NH₂ au bilan neutre, mais en milieu acide l’amine finale est protonée et en milieu basique l’acide est carboxylate. En acide, activation de C=O, attaque d’eau et transferts de H⁺ protonent l’azote avant rupture C−N ; les électrons de la liaison vont vers N, permettant le départ d’une amine ensuite protonée par le milieu. En base, addition de HO⁻ puis transferts et départ conduisent au carboxylate. La mésomérie de l’amide et son groupe partant moins favorable imposent souvent des conditions plus vigoureuses que pour un ester. Il faut écrire les formes réellement dominantes au pH choisi.")),
    lesson("31. Substitution nucléophile d’acyle : addition puis élimination", "PC — dérivés d’acides", "acylation",
        P("Réactivité.", "Un dérivé RCOZ possède un C carbonyle électrophile et un substituant Z éliminable après formation de l’intermédiaire tétraédrique. Sa réactivité dépend de l’activation du carbonyle et de l’aptitude de Z à partir. Les chlorures et anhydrides sont souvent plus réactifs que les esters ; les amides sont fortement stabilisées par mésomérie."),
        F("RCOZ + Nu → intermédiaire tétraédrique → RCONu + Z\nRCOCl + 2 R′NH₂ → RCONHR′ + R′NH₃⁺Cl⁻\nRCOCl + R′NH₂ + base → amide + base protonée + Cl⁻"),
        P("Démonstration.", "L’amine attaque C=O, O reçoit le doublet π, puis reforme C=O en expulsant Cl⁻. Une déprotonation donne l’amide neutre. HCl ou son équivalent protonique doit être piégé : un second équivalent d’amine peut être consommé uniquement comme base, ou une base séparée peut assurer cette fonction."),
        P("Exemple.", "Avec 10 mmol de chlorure d’acyle et seulement 10 mmol d’amine sans base externe, une fraction de l’amine devient ammonium non nucléophile. Une simple règle « 1:1 » ne suffit pas à annoncer 10 mmol d’amide. Si 20 mmol d’amine sont disponibles, le modèle bilan 1:2 permet cette quantité théorique."),
        P("Paracétamol.", "L’acylation de l’azote du p-aminophénol par un agent adapté construit une amide en présence d’un OH phénolique. La chimiosélectivité dépend des conditions et se vérifie ensuite : on ne considère pas toutes les fonctions comme des nucléophiles équivalents."),
        P("Peptides : PC.", "La liaison peptidique est une amide −CO−NH− reliant deux résidus d’acides α-aminés. Gly−Ala, H₂N−CH₂−CO−NH−CH(CH₃)−CO₂H dans une écriture neutre, possède une extrémité amino N-terminale, une extrémité carboxyle C-terminale et une chaîne latérale CH₃ sur le résidu alanine. Ala−Gly possède un autre ordre et une autre connectivité. Pour une synthèse dirigée, protection du NH₂ de l’acide activé et du CO₂H du partenaire nucléophile peut éviter les auto-couplages ; activation, configuration et déprotection doivent être contrôlées. Les formes ioniques changent avec le pH.")),
    lesson("32. Activation : rendre la bonne fonction réactive", "Sup option PC → PC", "acylation",
        P("Deux leviers.", "Activer un nucléophile consiste par exemple à déprotoner ROH en RO⁻. Activer un électrophile consiste à protoner un alcool pour faciliter H₂O comme départ, à fabriquer un sulfonate, ou à convertir un acide en dérivé acylant. Activation et catalyse ne désignent pas toujours la même consommation de réactifs."),
        F("ROH → ROTs : rupture O−H puis formation O−S ; liaison C−O conservée\nROTs + Nu⁻ → RNu + OTs⁻ : SN2 possible, inversion au C réactif\nRCO₂H + R′NH₂ ⇌ sel ammonium carboxylate, avant activation"),
        P("Stéréochimie.", "La préparation d’un sulfonate sur O conserve la configuration géométrique du C portant l’alcool, car C−O n’est pas rompue. La substitution ultérieure au C peut l’inverser. Une séquence activation→SN2 ne comporte donc pas deux inversions identiques."),
        P("Exemple.", "Un alcool secondaire transforme son OH, mauvais groupe partant, en un sulfonate ; un azoture peu basique peut ensuite le remplacer par SN2. Une base forte peut au contraire provoquer E2. Pour une amide, un acide et une amine seuls forment souvent d’abord un sel : l’activation résout une difficulté de réactivité réelle."),
        P("Technique.", "Écrire la fonction visée, le type d’activation et le bilan des sous-produits. Identifier les autres fonctions susceptibles de réagir avec l’agent activant. Une banque de réactions fournit les conditions nécessaires, dont le choix peut différer d’un exemple de cours à l’autre.")),
    lesson("33. Protection : conserver une fonction pendant une étape incompatible", "Sup — PCSI option PC", "protection",
        P("Principe.", "Une protection transforme temporairement une fonction gênante, résiste à l’étape désirée puis se retire sélectivement. Le coût est plusieurs opérations supplémentaires, des pertes de rendement et des déchets. Un groupe protecteur est choisi à partir de sa stabilité et des fonctions présentes."),
        F("Carbonyle + diol ⇌ acétal cyclique + H₂O, catalyse acide\nAcétal généralement stable envers bases/Grignard ; hydrolyse aqueuse acide\nRendement global de 3 étapes : yglobal=yprotection·yréaction·ydéprotection"),
        P("Exemple.", "Pour réaliser une addition organomagnésienne sur une fonction tout en conservant un autre carbonyle, protéger sélectivement celui qui doit survivre peut être nécessaire. Former l’acétal, éliminer eau et acide avant RMgX, effectuer l’addition et son traitement, puis hydrolyser l’acétal selon une séquence compatible."),
        P("Bilan.", "Trois étapes à 90 %, 85 % et 95 % donnent yglobal≈72,7 %. Une route directe compatible à 80 % peut donc être préférable. Mais un saut de protection menant à un mélange inutilisable n’est pas une optimisation : le nombre d’étapes seul n’évalue pas la qualité d’une route."),
        P("Technique.", "Établir une matrice fonction/réactif/conditions, annoncer pourquoi une protection est sélective et démontrer sa récupération par caractérisation. Les séquences du laboratoire comparent compatibilités et bilans déclarés ; elles ne prédisent pas les rendements de toute polyfonctionnalité."),
        P("Autres fonctions : PC.", "Un carboxyle peut être protégé en ester, un amino par une amide ou un carbamate de banque, un hydroxyle par un ester, un éther ou un groupe silylé fourni. Chacun résiste à certaines conditions et se retire par d’autres. Une protection ester n’est pas compatible avec un organomagnésien simplement parce qu’elle masque l’acidité : son carbonyle peut subir une addition. Protéger puis déprotéger avec deux réactions connues ne suffit pas ; il faut choisir la fenêtre de stabilité de toute la route. Un groupe benzyle peut se retirer par hydrogénolyse adaptée mais une double liaison à conserver pose alors un problème de chimiosélectivité.")),
    lesson("34. Aldolisation et crotonisation : construire un motif conjugué", "PC — énolates et création C−C", "aldol",
        P("Étapes.", "Une base retire un Hα d’un carbonyle énolisable. Le C de l’énolate attaque le carbonyle d’un second partenaire ; après protonation, un β-hydroxycarbonyle apparaît. Une déshydratation ultérieure, appelée crotonisation, donne un carbonyle α,β-insaturé. Aldolisation et crotonisation doivent être distinguées."),
        F("RCOCH₂R′ → énolate ; énolate + R″CHO → β-hydroxycarbonyle\nβ-hydroxycarbonyle → carbonyle α,β-insaturé + H₂O\nBenzaldéhyde + acétophénone → chalcone + H₂O (bilan condensé)"),
        P("Choix croisé.", "Deux carbonyles tous deux énolisables peuvent donner plusieurs auto- et aldolisations croisées. Le benzaldéhyde n’a pas de Hα : il joue l’accepteur avec un donneur énolisable choisi. Préformer un énolate et contrôler l’ordre d’addition peut améliorer une sélectivité croisée."),
        P("Exemple.", "Acétophénone PhCOCH₃ et benzaldéhyde PhCHO donnent d’abord PhCOCH₂CH(OH)Ph ; déshydratation donne PhCOCH=CHPh. Les Hα du donneur et l’oxygène du carbonyle accepteur permettent de suivre les atomes jusqu’à l’eau éliminée. L’isomère E est souvent favorisé, sans imposer un pourcentage universel."),
        P("Technique.", "Repérer les Hα, identifier donneur et accepteur, tracer la nouvelle liaison puis vérifier la position β de OH et α,β de C=C. Une aldolisation intramoléculaire ajoute une contrainte de taille de cycle ; la dilution peut influencer compétition intra/intermoléculaire."),
        P("Crotonisation E1cb : PC.", "En base, retirer Hα forme d’abord un carbanion/énolate stabilisé, puis l’élimination de HO⁻ crée le système α,β-conjugué. C’est une élimination par la base conjuguée E1cb, différente d’E1 par carbocation et d’E2 concertée. La stabilisation de l’intermédiaire et la conjugaison finale rendent possible un départ qui serait défavorable dans une simple substitution d’un alcool non activé."),
        P("C-alkylation d’énolate : PC.", "Un énolate de cétone peut attaquer un halogénure alkyle accessible par SN2 et créer Cα−Calkyle. Deux sites α d’une cétone dissymétrique donnent des énolates régioisomères : base encombrée, basse température et déprotonation rapide favorisent souvent le site le moins encombré sous contrôle cinétique ; une énolisation réversible peut sélectionner l’énolate plus stable. Base, solvant et temps restent des données nécessaires. Un aldéhyde électrophile peut s’auto-aldoliser en concurrence, ce qui empêche de généraliser simplement l’alkylation de cétone. L’énolate est ambident C/O : compter les conditions et orbitales fournies, pas une charge localisée unique.")),
    lesson("35. Michael et Wittig : deux constructions C−C différentes", "PC — réactions fournies et stratégies", "michaelwittig",
        P("Michael.", "Un carbonyle α,β-insaturé possède un site électrophile au C carbonyle et un au Cβ. Des nucléophiles adaptés, comme certains énolates stabilisés, peuvent donner une addition conjuguée 1,4 ; le carbonyle réapparaît après protonation/tautomérie. Des réactifs plus durs favorisent souvent 1,2, selon conditions."),
        F("Nu⁻ + RCO−CH=CH₂ → RCO−CH₂−CH₂Nu (après protonation)\nWittig : R₂C=O + Ph₃P=CHR′ → R₂C=CHR′ + Ph₃P=O\nYlure : Ph₃P⁺−C⁻HR′ ↔ Ph₃P=CHR′"),
        P("Wittig.", "Un ylure de phosphore construit C=C en remplaçant l’oxygène du carbonyle par le carbone de l’ylure. Le bilan d’atomes place O sur Ph₃P=O. Ylures non stabilisés et stabilisés ont souvent des tendances Z et E différentes, mais sel, base, solvant et protocole interdisent d’en faire une règle absolue."),
        P("Exemple.", "Benzaldéhyde PhCHO et Ph₃P=CH₂ donnent styrène PhCH=CH₂ : ce produit n’a pas d’E/Z. Une addition d’un énolate d’acétoacétate à une énone peut donner un motif 1,5-dicarbonylé après protonation, alors qu’une addition 1,2 produit un alcool allylique."),
        P("Technique.", "Comparer les connectivités finales avant les noms de réaction, compter le carbone introduit et vérifier les doubles liaisons restantes. Une sélectivité d’addition 1,4 ne se déduit pas seulement de la présence d’une forme mésomère.")),
    lesson("36. Aromatiques : orienter la SEA et ordonner les étapes", "PC — substitution électrophile aromatique", "aromatique",
        P("Mécanisme.", "Une liaison π aromatique attaque un électrophile E⁺ et forme un intermédiaire σ de Wheland qui a perdu temporairement l’aromaticité. La déprotonation rétablit le cycle conjugué. Les substituants affectent à la fois la vitesse et les positions relatives possibles."),
        F("Donneurs +M, souvent ortho/para ; −NO₂, −CN, −COR : souvent méta\nHalogènes : désactivants par −I mais ortho/para-directeurs\nFriedel–Crafts généralement indisponible sur noyaux fortement désactivés, dont nitrobenzène"),
        P("Justification.", "Comparer les formes du complexe σ : un groupe donneur peut stabiliser les attaques ortho/para ; un attracteur −M les pénalise davantage que méta. Ce raisonnement explique l’orientation, mais les proportions exigent les barrières et les conditions ; additionner des dipôles de liaison ne donne pas directement un rapport d’isomères."),
        P("Exemple de stratégie.", "Pour une nitroacétophénone méta, acyler le benzène en acétophénone avant la nitration : COCH₃ dirige alors vers méta. Nitrer d’abord donnerait un noyau trop désactivé pour une Friedel–Crafts usuelle. Une alkylation peut réarranger et polyalkyler ; une acylation puis réduction adaptée peut éviter certains de ces problèmes."),
        P("Technique.", "Distinguer orientation d’un substituant et activation globale, vérifier incompatibilités avec l’acide de Lewis et réexaminer les directeurs après chaque étape. Une réaction radicalaire sur chaîne latérale n’est pas une SEA sur le noyau.")),
    lesson("37. CLOA et recouvrement : normaliser les orbitales", "PC ; prolongement algébrique guidé", "orbitales",
        P("Objets.", "Une orbitale moléculaire ψ est une combinaison d’orbitales atomiques φA,φB normalisées. S=∫φA*φB dτ est sans dimension. Pour deux orbitales réelles similaires, les combinaisons symétrique et antisymétrique ont des normalisations différentes lorsque S n’est pas nul."),
        F("ψ+ = (φA+φB)/√[2(1+S)]\nψ− = (φA−φB)/√[2(1−S)]\nCas général : Hc=ESc ; c†Sc=1"),
        P("Démonstration.", "Intégrer |φA±φB|² donne 1+1±2S. Diviser par 2(1±S) garantit une norme unité. S doit satisfaire |S|<1 pour deux fonctions indépendantes ; S→1 signifie une base presque redondante et rend la combinaison antisymétrique mal conditionnée."),
        P("Exemple.", "Pour S=0,20, les dénominateurs sont √2,4≈1,549 et √1,6≈1,265. La normalisation ne détermine pas à elle seule l’énergie ; il faut les éléments de H. Une combinaison constructive peut être liante dans un problème donné, mais le signe d’un coefficient dépend aussi de la phase choisie pour les orbitales de base."),
        P("Technique.", "Séparer dessin des phases, normalisation et diagonalisation. L’amplitude signée d’un lobe n’est pas une charge positive ou négative ; |ψ|² donne une densité de probabilité. Le labo fournit un Hamiltonien modèle et annonce ses approximations.")),
    lesson("38. Hückel et orbitales frontières : passer d’un graphe à une réactivité", "PC ; extension numérique accompagnée", "orbitales",
        P("Modèle.", "Dans l’approximation de Hückel, une orbitale p par C conjugué, un recouvrement négligé, une énergie α sur chaque site et un couplage β<0 entre voisins définissent un Hamiltonien réel. Les niveaux et coefficients se calculent par diagonalisation. Le remplissage porte deux électrons au plus par orbitale."),
        F("H = αI + βA, A : matrice d’adjacence\nChaîne m sites : Ej=α+2β cos[jπ/(m+1)]\nButadiène : HO=α+0,618β ; BV=α−0,618β ; écart=1,236|β|"),
        P("Exemple.", "Quatre électrons π du butadiène occupent les deux niveaux les plus bas. La HO a des coefficients dont les phases peuvent être opposées aux deux extrémités selon une phase globale arbitraire. Les densités de site impliquent carrés des amplitudes occupées ; le recouvrement de réaction doit aussi conserver les signes relatifs."),
        P("Réactivité.", "Une HO d’un nucléophile et une BV d’un électrophile rapprochées en énergie et de recouvrement adapté favorisent une interaction. Les gros lobes donnent une lecture qualitative de régiosélectivité pour des orbitales dissymétriques fournies, complétée par géométrie et encombrement. Le modèle ne prédit pas un rendement de laboratoire."),
        P("Technique.", "Déclarer α,β et la connectivité, vérifier orthonormalité et nombre d’électrons puis comparer deux orientations par leurs phases et amplitudes terminales. Un diene bloqué s-trans ne satisfait pas la géométrie de cycloaddition même avec un écart HO/BV favorable.")),
    lesson("39. Diels–Alder : concertation, s-cis et endo", "PC — cycloadditions", "dielsalder",
        P("Bilan.", "Une cycloaddition [4+2] combine un diène conjugué et un diénophile pour construire un cycle à six C avec deux nouvelles liaisons σ et une double liaison résiduelle. Le diène doit pouvoir adopter une disposition s-cis. Un diène fixé s-trans est géométriquement inadapté au chemin concerté usuel."),
        F("4 électrons π du diène + 2 du diénophile → cycle à 6 centres\nDeux liaisons σ nouvelles ; liaison π résiduelle entre C2 et C3 du diène\nSubstituants cis du diénophile ⇒ relation cis conservée dans l’adduit"),
        P("Endo/exo.", "Avec un diénophile portant un groupe π attracteur, l’adduit endo est souvent favorisé cinétiquement par des interactions et une géométrie adaptées. Le produit exo peut être plus stable selon le système. Réversibilité et température peuvent donc modifier la composition ; aucune règle endo ne remplace les données d’activation."),
        P("Exemple.", "Cyclopentadiène et anhydride maléique construisent un adduit bicyclique. Le diène est contraint dans une géométrie favorable ; le diénophile pauvre en électrons favorise une demande électronique normale. Une estimation avec ΔΔG‡=3 kJ·mol⁻¹ à 298 K donne un rapport ≈3,36 seulement si les préfacteurs sont comparables et les voies irréversibles."),
        P("Technique.", "Numéroter les six centres, placer les deux nouvelles liaisons, conserver cis/trans du diénophile et vérifier s-cis avant la discussion orbitalaire. La structure endo se définit par la géométrie de l’adduit, pas simplement par une étiquette sur un histogramme.")),
    lesson("40. Rétrosynthèse : choisir les coupures et l’ordre des fonctions", "Sup option PC → PC", "retrosynthese",
        P("Démarche.", "Partir de la cible, repérer fonctions et squelette puis couper mentalement une liaison formée par une réaction connue. Les synthons sont des fragments conceptuels chargés ; les réactifs équivalents sont des espèces réalisables. Revenir ensuite dans le sens direct pour vérifier compatibilités et sélectivités."),
        F("Alcool tertiaire R₁R₂R₃C−OH ← cétone R₁COR₂ + R₃MgX\nChalcone ← acétophénone + benzaldéhyde\nRendement global linéaire = ∏ yi ; convergence : comparer la plus longue séquence linéaire"),
        P("Exemples.", "L’aspirine s’obtient conceptuellement par acylation du OH phénolique de l’acide salicylique. Le paracétamol par N-acylation du p-aminophénol. La chalcone par condensation croisée suivie de déshydratation. Ces trois cibles font comparer activation d’acyle, chimiosélectivité et création C−C, puis purification et caractérisation."),
        P("Ordre.", "Effectuer Friedel–Crafts avant une nitration désactivante, protéger un carbonyle avant un réactif qui doit l’épargner, retirer les milieux protiques avant un organomagnésien. Une route n’est validée qu’après reconstruction directe avec les conditions et le bilan d’atomes."),
        P("Technique.", "Définir un réactif limitant pour chaque étape, distinguer transformation théorique, conversion, sélectivité et rendement isolé. Le labo compare des routes dont les rendements et masses sont déclarés ; il invite à discuter leur plausibilité et les mesures nécessaires.")),
    lesson("41. Synthèse au laboratoire : isoler, mesurer et réduire les pertes", "Sup — TP PCSI ; consolidation PC", "retrosynthese",
        P("Chaîne expérimentale.", "Une synthèse relie choix des quantités, montage et suivi, arrêt de réaction, extraction, lavage, séchage, purification puis caractérisation. Un reflux garde un mélange chauffé en condensant ses vapeurs ; une distillation sépare selon volatilité. Une recristallisation sépare suivant les solubilités et leurs variations avec la température."),
        F("yisolé = nproduit,pur / nproduit,théorique\nÉconomie d’atomes = Mproduit désiré / Σνi Mi,réactifs (équation équilibrée)\nPMI = masse totale entrante / masse produit ; E-factor = masse déchets / masse produit"),
        P("Exemple.", "5,00 g d’acide salicylique (138,12 g·mol⁻¹) correspondent à 36,20 mmol. Pour une transformation 1:1 en aspirine (180,16 g·mol⁻¹), la masse théorique est 6,522 g. Isoler 4,80 g de pureté massique 95 % donne 4,56 g de produit pur, soit 69,9 %, et non 73,6 % de produit pur."),
        P("Indicateurs.", "Pour un bilan massique complet et un périmètre identique, E-factor=PMI−1 si toute entrée hors produit devient déchet. Le traitement de l’eau, des solvants recyclés et des catalyseurs doit être annoncé. Une bonne économie d’atomes n’implique pas un petit PMI si des litres de solvant sont consommés."),
        P("Technique.", "Prévoir une méthode de contrôle qui distingue identité, pureté et quantité : IR/RMN, CCM, point de fusion comparé, dosage si adapté. Les laboratoires numériques forment le raisonnement du TP ; ils ne remplacent pas un protocole encadré, ses fiches de sécurité et sa gestion des déchets.")),
    lesson("42. Polymères : une chimie des répétitions et des distributions", "PC ; prolongements statistiques accompagnés", "polymeres",
        P("Deux familles.", "Une polymérisation en chaîne fait croître des centres actifs ; une polymérisation par étapes fait réagir entre elles les fonctions de toutes les tailles de molécules. Polycondensation et polyaddition décrivent des bilans d’élimination différents et ne coïncident pas exactement avec chaîne/étapes."),
        F("Carothers, bifonctionnels équilibrés : Xn=1/(1−p)\nDéséquilibre r≤1 : Xn=(1+r)/(1+r−2rp)\nDistribution géométrique idéale : xn=(1−p)p^(n−1) ; dispersité Đ≈1+p"),
        P("Exemple.", "Avec r=1, p=0,99 donne Xn=100 ; p=0,999 donne 1000. Si r=0,98 et p=0,99, Xn=1,98/(1,98−1,9404)=50. Une petite erreur de stœchiométrie limite donc fortement la longueur, même si la conversion de fonction est élevée."),
        P("Hypothèses.", "Le calcul suppose monomères bifonctionnels, réactivité des fonctions indépendante de la taille, absence de cyclisation et bilan de groupes adapté ; p est la fraction consommée des fonctions initialement limitantes pour r≤1. Des fonctions de valence supérieure permettent un réseau et une gélification hors du modèle linéaire. Les masses Mn et Mw sont des moyennes différentes d’une distribution."),
        P("Lien synthèse.", "La synthèse d’une liaison ester ou amide répétée utilise les mêmes notions d’activation et de départ que les petites molécules. La pureté fonctionnelle, la stœchiométrie et l’élimination d’un sous-produit deviennent des leviers du matériau final. Vérifier les hypothèses avant d’extrapoler Xn à un polymère réel."),
        F("Diacide HO₂C−A−CO₂H + diol HO−B−OH ⇒ motif polyester [−CO−A−CO−O−B−O−]\nDiacide + diamine H₂N−B−NH₂ ⇒ motif polyamide [−CO−A−CO−NH−B−NH−]\nAlcène CH₂=CHR ⇒ motif vinylique [−CH₂−CH(R)−] par voie de chaîne adaptée"),
        P("Monomères : PC.", "Le nylon 6,6 associe une diamine à six C et un diacide à six C : le motif est [−NH−(CH₂)₆−NH−CO−(CH₂)₄−CO−], à distinguer des six C du diacide incluant ses deux carbonyles. Un polyester aromatique comme PET associe diol et diacide aromatique suivant la banque choisie. Une polymérisation d’alcène par coordination peut être décrite par un cycle fourni : coordination du monomère puis insertion dans la liaison métal−chaîne font croître le motif vinylique. Ce cycle n’est pas une condensation ester et ne suit pas les mêmes populations de Carothers.")),
]


# Les exercices, sources et liens sont complétés ci-dessous ; tout est exportable.
EXERCISES = [
    exercise("1. Le nitro : octets, charges et formes limites", "Sup", "electrons",
        "Construire deux formes de Lewis de CH₃NO₂ sans dépasser l’octet de N. Donner les charges formelles sur N et les deux O, compter les électrons de valence, puis expliquer pourquoi ces formes ne sont pas deux molécules en équilibre. Identifier la différence avec une tautomérie carbonyle/énol.",
        "CH₃NO₂ possède 4+3×1+5+2×6=24 électrons de valence. Le N est lié au C, doublement à un O et simplement à l’autre : quatre liaisons, aucun doublet, donc qN=5−0−4=+1. O doublement lié a q=6−4−2=0 ; O simplement lié et portant trois doublets a q=6−6−1=−1. La deuxième forme échange les rôles des O, sans déplacer aucun noyau. Leur charge totale vaut 0 et chacune respecte l’octet. La molécule réelle est délocalisée ; ce dessin ne définit pas une conversion temporelle. Une tautomérie énol/carbonyle déplace un H et change une connectivité σ : elle relie des espèces distinctes, et exige un mécanisme de transfert de proton."),
    exercise("2. Une attaque sur C=O qui respecte l’octet", "Sup", "electrons",
        "Pour l’addition de CH₃⁻, employé ici comme synthon, sur le méthanal, écrire l’intermédiaire avant puis après protonation. Décrire l’origine et la destination des deux flèches de la première étape. Vérifier charge et atomes. Préciser quel réactif équivalent pourrait remplacer le synthon dans une synthèse réalisable.",
        "Le doublet du carbone de CH₃⁻ attaque le C de H₂C=O ; le doublet π C=O se déplace vers O. On obtient CH₃CH₂O⁻, qui possède une nouvelle liaison C−C et une liaison C−O simple ; C conserve quatre liaisons et O porte la charge −1. Ajouter un proton avec un donneur compatible après l’addition donne CH₃CH₂OH. Le bilan avant protonation conserve deux C, cinq H, un O et la charge −1. Un dessin qui garderait C=O tout en ajoutant CH₃ donnerait un C à cinq liaisons et doit être rejeté par l’octet. CH₃MgBr en milieu anhydre, puis hydrolyse/protonation terminale, est un équivalent synthétique du carbone nucléophile ; CH₃⁻ libre n’est pas le protocole proposé."),
    exercise("3. Une conversion acido-basique n’est pas une fraction de tampon", "Sup", "acidebase",
        "À 25 °C en eau, mélanger des quantités équimolaires d’acide acétique et NH₃, sans produits initiaux. Les pKa fournis sont 4,76 et 9,25. Calculer K puis la fraction convertie avec activités assimilées aux concentrations. Comparer à la fraction d’acétate dans un tampon à pH=5,76.",
        "La réaction CH₃CO₂H+NH₃⇌CH₃CO₂⁻+NH₄⁺ a K=10^(9,25−4,76)=10^4,49≈3,09×10⁴. Si f=x/c₀, les deux produits ont concentration x et les deux réactifs c₀−x, donc K=f²/(1−f)². Ainsi f=√K/(1+√K)≈0,9943, soit 99,43 %. Dans le tampon, le pH est imposé par un autre bilan : [A⁻]/[HA]=10^(5,76−4,76)=10, et fA⁻=10/11=90,91 %. Les valeurs diffèrent parce que le premier problème conserve deux stocks réactifs et produit les deux formes conjuguées, tandis que le second fixe une activité du proton. Utiliser K/(1+K) pour la conversion équimolaire confondrait ces conditions."),
    exercise("4. Basicité, nucléophilie et solvant", "Sup → PC", "acidebase",
        "On veut substituer un bromure secondaire en limitant l’élimination. Comparer qualitativement I⁻ et tert-BuO⁻, puis expliquer pourquoi un classement de nucléophilie doit nommer un substrat et un solvant. Enfin, estimer l’équilibre entre aniline et acide acétique en eau, avec pKa(anilinium)=4,6 et pKa(acide)=4,8.",
        "I⁻ est peu basique et polarisable : une substitution est plausible si l’accès au C est suffisant. tert-BuO⁻ est une base forte encombrée ; arracher Hβ et conduire à E2 peut être plus facile qu’attaquer ce C. Ce raisonnement ne garantit pas un rendement et doit être confronté à la classe du substrat, au solvant et à la température. La nucléophilie mesure une vitesse vers un électrophile donné ; la basicité compare un équilibre de protonation. Pour PhNH₂+CH₃CO₂H⇌PhNH₃⁺+CH₃CO₂⁻, K≈10^(4,6−4,8)=0,63. À stocks égaux idéaux, f=√0,63/(1+√0,63)≈44 %. La disponibilité de l’amine nucléophile dépend donc du milieu ; une acidification peut réduire fortement sa réactivité d’acylation."),
    exercise("5. SN2 : quand le pseudo-premier ordre est permis", "Sup", "sn2",
        "Une SN2 a k₂=0,10 L·mol⁻¹·s⁻¹. Comparer a) [S]₀=0,010 mol·L⁻¹, [Nu]₀=1,00 mol·L⁻¹ ; b) deux concentrations initiales égales à 0,10 mol·L⁻¹. Calculer le temps de demi-réaction dans chaque approximation adaptée et indiquer une mesure qui teste l’ordre en nucléophile.",
        "Dans a), consommer tout S ne réduit Nu que de 1 %. On peut prendre [Nu]≈1,00 mol·L⁻¹ : kobs=k₂[Nu]=0,10 s⁻¹, [S]=[S]₀e^(−kobs t) et t₁/₂=ln2/0,10=6,93 s. Dans b), [Nu]=[S] pendant la réaction, donc −d[S]/dt=k₂[S]² et 1/[S]−1/[S]₀=k₂t. À moitié, t₁/₂=1/(k₂[S]₀)=100 s. Utiliser une exponentielle dans b) donnerait une mauvaise loi. Pour tester l’ordre, mesurer v₀ à [S]₀ fixé et doubler [Nu]₀ : v₀ doit doubler dans le schéma SN2, tant que les autres conditions restent identiques. L’unité L·mol⁻¹·s⁻¹ de k₂ fournit un contrôle dimensionnel de ces deux calculs."),
    exercise("6. Williamson : choisir le bon côté de la coupure", "Sup", "sn2",
        "Proposer une synthèse de l’éther tert-butyl méthylique par une SN2 de Williamson. Deux coupures sont envisagées : méthanolate+bromure tert-butylique, ou tert-butanolate+iodométhane. Choisir et justifier le couple. Que deviendrait la notion d’inversion si l’halogénure portait un centre stéréogène ?",
        "La coupure favorable place le groupe le moins encombré sur l’électrophile : tert-BuO⁻+CH₃I→tert-BuOCH₃+I⁻. Le C méthyle est accessible à l’attaque arrière et ne porte pas de Cβ, donc aucune E2 de ce substrat ne concurrence l’attaque. Avec CH₃O⁻ et tert-BuBr, le C tertiaire est trop encombré pour la SN2 usuelle et la base peut arracher un Hβ pour former isobutène. L’encombrement du nucléophile tert-butanolate n’est pas nul mais l’électrophile méthyle rend la voie choisie beaucoup plus pertinente. Sur un C stéréogène accessible, une SN2 inverse la disposition géométrique ; le descripteur R/S doit être recalculé, car changer le groupe partant peut changer les priorités CIP."),
    exercise("7. Une solvolyse de premier ordre", "Sup", "sn1",
        "Une solvolyse compatible avec une ionisation déterminante laisse 30 % du substrat après 80 s. Estimer k₁ et t₁/₂. La quantité restante change-t-elle si la concentration initiale est divisée par deux ? Discuter ce qu’un résultat de vitesse indépendant d’un nucléophile ajouté permet réellement de conclure.",
        "La loi limite est [S](t)/[S]₀=e^(−k₁t). Donc k₁=−ln0,30/80≈0,01505 s⁻¹ et t₁/₂=ln2/k₁≈46,1 s. Diviser [S]₀ par deux conserve la fraction restante à un temps donné, mais divise sa concentration absolue et sa vitesse initiale par deux. L’indépendance de la vitesse envers un nucléophile appuie une ionisation déterminante suivie d’un piégeage rapide, à conditions d’ionisation constantes. Elle ne prouve pas seule la présence d’un cation entièrement libre : paire d’ions, étape précédente et voies parallèles demandent des observations supplémentaires. Il faut examiner réarrangements éventuels et stéréochimie plutôt que transformer une seule mesure d’ordre en identification unique du mécanisme."),
    exercise("8. Carbocation et déplacement d’hydrure", "Sup → PC", "sn1",
        "Le départ d’un groupe X sur 3-méthylbutan-2-yl peut former un carbocation secondaire. Dessiner le squelette initial, proposer une migration d’hydrure permettant un cation plus substitué puis les produits de capture par l’eau. Expliquer pourquoi une SN2 sur le même substrat ne passe pas par cette séquence.",
        "Le substrat est CH₃−CH(X)−CH(CH₃)−CH₃. Après départ de X⁻, la charge est sur C2 : CH₃−CH⁺−CH(CH₃)−CH₃. Une migration du H lié à C3 vers C2 déplace le doublet C3−H et la charge vers C3 : CH₃−CH₂−C⁺(CH₃)−CH₃, cation tertiaire. La capture d’eau puis déprotonation donne 2-méthylbutan-2-ol ; une capture avant migration peut donner 3-méthylbutan-2-ol. La proportion dépend des vitesses concurrentes. La SN2 combine attaque et départ dans une étape, sans minimum carbocationique : cette migration d’un intermédiaire n’appartient pas à son schéma. Conserver les cinq C et tous les H montre que l’hydrure migre en interne et n’est pas ajouté depuis le solvant."),
    exercise("9. Conversion, sélectivité et rendement de produit", "Sup → PC", "competition",
        "Deux voies parallèles irréversibles consomment S avec λSN2=0,060 s⁻¹ et λE2=0,020 s⁻¹. À t=20 s, déterminer conversion, fractions des produits formés et quantité de produit SN2 rapportée au stock initial. Une purification récupère 85 % de ce produit ; déterminer le rendement isolé correspondant.",
        "λtotal=0,080 s⁻¹, donc [S]/[S]₀=e^(−1,6)=0,2019 et la conversion vaut 79,81 %. La sélectivité parmi les produits est λSN2/λtotal=0,75 pour substitution et 0,25 pour élimination, car les deux flux suivent le même stock S. Le produit de substitution représente 0,7981×0,75=0,5986, soit 59,86 % du stock initial. Une récupération de 85 % ramène le rendement isolé à 0,5986×0,85=50,88 %. Annoncer 75 % comme rendement isolé confondrait sélectivité, conversion et récupération. Ce calcul dépend de chemins parallèles sans retour ni transformation des produits ; il ne peut être extrapolé à une synthèse dont les constantes ne sont pas connues."),
    exercise("10. Détecter deux chemins avec l’ordre apparent", "PC", "competition",
        "Une consommation suit v=[S](k₁+k₂[Nu]) avec k₁=0,010 s⁻¹ et k₂=0,20 L·mol⁻¹·s⁻¹. Calculer kobs et la fraction attribuée au chemin bimoléculaire pour [Nu]=0,05 puis 0,20 mol·L⁻¹. Quel graphe permet d’identifier les deux contributions et quelle interprétation microscopique demeure à vérifier ?",
        "À 0,05 mol·L⁻¹, k₂[Nu]=0,010 s⁻¹ : kobs=0,020 s⁻¹ et le chemin bimoléculaire contribue 50 %. À 0,20 mol·L⁻¹, il contribue 0,040 s⁻¹ : kobs=0,050 s⁻¹ et sa fraction vaut 80 %. Le graphe kobs en fonction de [Nu] est une droite d’ordonnée à l’origine k₁ et de pente k₂. Deux concentrations ne suffisent pas à contrôler parfaitement une linéarité ; plusieurs points et incertitudes sont souhaitables. On peut proposer une voie unimoléculaire parallèle à une voie bimoléculaire, puis vérifier produits et stéréochimie pour les relier à SN1/SN2 ou à d’autres chemins. L’ordre apparent varie avec [Nu] : il n’est pas un entier unique décrivant tout le domaine de compétition."),
    exercise("11. E2 : déduire la géométrie avant Zaitsev", "Sup → PC", "elimination",
        "Énumérer les alcènes possibles par E2 du 2-bromobutane. Préciser le H retiré pour chaque connectivité et expliquer pourquoi E/Z-but-2-ène demandent deux arrangements anti distincts. Une base volumineuse peut-elle modifier la distribution sans supprimer l’exigence anti ?",
        "Le substrat CH₃−CHBr−CH₂−CH₃ porte des Hβ sur C1 et C3. Retirer un H de C1 forme CH₂=CH−CH₂−CH₃, but-1-ène, sans E/Z parce qu’un C porte deux H. Retirer un H de C3 forme CH₃−CH=CH−CH₃, but-2-ène E ou Z selon la conformation présentant ce H anti à Br. Une projection Newman sur C2−C3 permet de placer Br devant et le H opposé derrière, puis de suivre les positions des CH₃ lors de l’aplatissement. Une petite base favorise souvent le produit plus substitué ; une base encombrée peut arracher plus facilement un H terminal et accroître le but-1-ène. Elle ne rend pas toutes les orientations de liaison équivalentes : l’exigence de recouvrement anti reste dans le mécanisme E2 usuel."),
    exercise("12. Trans-diaxial : un produit moins substitué imposé", "PC", "elimination",
        "Pour trans-1-bromo-2-méthylcyclohexane, construire les deux chaises en gardant Br et CH₃ sur des faces opposées. Identifier la chaise réactive pour E2 et les Hβ anti disponibles. Le produit issu de l’élimination vers C2, plus substitué, est-il accessible dans cette chaise ?",
        "Le trans-1,2 possède une chaise diéquatoriale et, après basculement, une chaise diaxiale. En diéquatorial, Br n’est pas axial et l’E2 trans-diaxiale n’est pas disponible dans la géométrie usuelle. En diaxial, Br est axial en C1 et CH₃ axial de direction opposée en C2 ; le site axial anti de C2 est donc occupé par CH₃, et son H équatorial n’offre pas l’alignement requis. C6 possède en revanche un H axial anti à Br, permettant l’alcène entre C1 et C6. La voie vers C2 plus substituée est supprimée dans ce modèle de chaise, même si sa stabilité pourrait la favoriser après une autre voie ou une isomérisation. Ce contre-exemple montre pourquoi Zaitsev compare des chemins géométriquement autorisés et ne remplace pas le dessin des H."),
    exercise("13. Deux but-2-ènes et une bromation anti", "PC", "alcene",
        "Comparer la bromation par Br₂ de E-but-2-ène et de Z-but-2-ène en milieu achiral, en supposant le mécanisme bromonium puis ouverture anti. Dessiner les stéréoisomères et expliquer pourquoi la stéréospécificité ne signifie pas qu’une réaction ne donne jamais deux produits.",
        "Le bromonium ponté peut être formé depuis les deux faces, puis Br⁻ ouvre depuis la face opposée. Pour E-but-2-ène, les deux attaques anti conduisent à la même forme méso du 2,3-dibromobutane : ses centres ont configurations (2R,3S), équivalentes par symétrie à (2S,3R). Pour Z-but-2-ène, les produits sont (2R,3R) et (2S,3S), une paire d’énantiomères en proportions égales dans les hypothèses achirales. Ces deux réactifs stéréoisomères conduisent à des ensembles de produits différents : c’est la stéréospécificité. Elle est compatible avec une paire de produits pour l’un d’eux. Une indication « anti » seule ne fournit pas immédiatement R/S ; il faut dessiner les groupes et appliquer leurs priorités."),
    exercise("14. Un alcène, trois orientations à expliquer", "PC", "alcene",
        "À partir du propène, comparer les produits attendus par a) hydratation acide ; b) hydroboration puis oxydation ; c) HBr ionique. Donner pour chaque voie le rôle de la liaison π, l’intermédiaire ou l’étape concertée et la fonction finale. La voie b ajoute-t-elle deux OH ?",
        "La liaison π fournit des électrons dans chaque voie. En a), une protonation conduisant au cation secondaire puis une attaque d’eau et déprotonation donnent propan-2-ol : orientation Markovnikov dans ce schéma. En b), une addition concertée de H−B place préférentiellement B sur le C terminal ; l’oxydation remplace B par OH et donne propan-1-ol, anti-Markovnikov. H ajouté et OH final sont syn dans le suivi stéréochimique ; un seul OH est ajouté, ce n’est pas une dihydroxylation. En c), protonation puis capture par Br⁻ donnent principalement 2-bromopropane. Le propène ne crée pas ici de centre chiral dans a ou c. Les conditions annoncées distinguent ces voies ; le nom du substrat seul ne définit ni l’orientation ni le mécanisme."),
    exercise("15. Réduction partielle d’une triple liaison", "PC", "alcyne",
        "Construire Z-but-2-ène, E-but-2-ène puis butane à partir du but-2-yne, à l’aide d’une banque donnant H₂/Lindlar, une réduction par métal dissous et H₂/catalyseur non sélectif. Expliquer pourquoi « un équivalent d’H₂ » sans indication de catalyseur n’est pas un protocole suffisant.",
        "Le but-2-yne CH₃−C≡C−CH₃ donne Z-but-2-ène par l’addition syn d’H₂ sur catalyseur de Lindlar, choisi pour arrêter la réduction au stade alcène. Une réduction partielle par métal dissous dans les conditions fournies conduit globalement à l’addition anti et à E-but-2-ène. Un catalyseur d’hydrogénation non sélectif avec assez de H₂ permet l’addition de deux molécules et donne butane. Le bilan est donc une ou deux additions, mais la répartition de réactif entre molécules compte : avec un catalyseur qui réduit rapidement l’alcène, un équivalent global peut produire un mélange d’alcyne restant et d’alcane plutôt qu’un alcène pur. L’arrêt sélectif dépend de la cinétique et du catalyseur, pas de la stœchiométrie seule."),
    exercise("16. L’énol doit être redessiné", "PC", "alcyne",
        "Une banque donne l’hydratation acide catalysée par Hg²⁺ d’un alcyne terminal. Appliquer au prop-1-yne puis à l’acétylène, dessiner l’énol et le produit carbonylé. Comparer à une hydroboration/oxydation adaptée du prop-1-yne. Pourquoi ces couples énol/carbonyle ne sont-ils pas mésomères ?",
        "Pour CH₃−C≡CH, l’hydratation Markovnikov forme l’énol CH₃−C(OH)=CH₂, qui tautomérise en CH₃−CO−CH₃, propanone. Pour HC≡CH, l’énol CH₂=CHOH donne CH₃CHO, éthanal : il ne faut donc pas annoncer une méthylcétone sans cette exception. Une hydroboration/oxydation adaptée du prop-1-yne place OH sur le C terminal dans l’énol CH₃−CH=CHOH, puis donne CH₃CH₂CHO, propanal. Chaque tautomérie déplace un H et modifie une liaison σ O−H/C−H en plus de π ; elle relie des espèces constitutionnellement distinctes. Une mésomérie n’aurait déplacé que des électrons à noyaux fixes. Le carbone terminal de l’alcyne doit être suivi jusqu’au produit pour éviter une inversion de fonction finale."),
    exercise("17. Fermer une chaîne radicalaire", "PC", "radical",
        "Écrire deux étapes de propagation conduisant du propène et HBr au 1-bromopropane en présence d’un initiateur adapté. Identifier le radical carboné et vérifier le bilan net. Proposer une terminaison et expliquer pourquoi le résultat ne se transpose pas automatiquement à HCl.",
        "Br· attaque le C terminal de CH₂=CHCH₃ : BrCH₂−CH·−CH₃ est le radical secondaire. Celui-ci prend H à HBr : BrCH₂CH₂CH₃+Br·. Additionner les deux équations annule Br· et l’intermédiaire ; le bilan est propène+HBr=1-bromopropane. Coupler deux radicaux carbonés ou deux Br· constitue une terminaison, qui consomme deux porteurs de chaîne au lieu d’en régénérer un. L’orientation découle du radical formé, sans carbocation. Une chaîne efficace exige que ses étapes de propagation soient suffisamment favorables et rapides ; les énergies de liaison H−Cl, H−Br, H−I et les additions radicalaires diffèrent. La seule présence d’un peroxyde ne justifie donc pas le même bilan utile avec tous les HX."),
    exercise("18. Une racine carrée qui révèle la terminaison", "PC — prolongement quantitatif", "radical",
        "Un modèle stationnaire prend Ri=2×10⁻⁸ mol·L⁻¹·s⁻¹, kt=10⁷ L·mol⁻¹·s⁻¹ et Ri=2kt[R·]². Calculer [R·]. Si la propagation vaut v=kp[S][R·], que devient v quand Ri est multiplié par 9 ? Donner les conditions d’application et le sens d’une très faible concentration radicalaire.",
        "La conservation stationnaire donne [R·]=√(Ri/(2kt))=√(10⁻¹⁵)=3,16×10⁻⁸ mol·L⁻¹. L’unité suit (mol·L⁻¹·s⁻¹)/(L·mol⁻¹·s⁻¹)=mol²·L⁻² avant la racine. À kp et [S] inchangés, v est proportionnelle à √Ri : multiplier Ri par 9 multiplie v par 3, pas par 9. Le résultat suppose régime après initiation initiale, terminaison principalement bimoléculaire entre les radicaux considérés, absence d’inhibiteur dominant et substrat encore disponible. Une concentration minuscule ne signifie pas absence de réaction : le même radical peut effectuer de nombreux cycles de propagation avant terminaison. La convention du facteur 2 doit être conservée entre définition de Ri et équation de terminaison."),
    exercise("19. Carbonyle, hydrure et stéréochimie", "Sup", "carbonyle",
        "Réduire propanone puis butan-2-one par un transfert d’hydrure suivi de protonation. Dessiner les charges et indiquer s’il se crée un centre stéréogène. Dans un milieu achiral, quelle composition stéréochimique est attendue pour le butan-2-ol isolé ? Quelle donnée supplémentaire pourrait rendre les faces inéquivalentes ?",
        "L’hydrure fournit une paire à C=O tandis que π se déplace vers O. Propanone donne (CH₃)₂CH−O⁻ puis propan-2-ol ; le C porte deux CH₃ identiques et n’est pas stéréogène. Butan-2-one donne CH₃−CH(O⁻)−CH₂CH₃ puis butan-2-ol ; le C porte OH, H, CH₃ et CH₂CH₃, quatre groupes différents. Ses deux faces équivalentes dans les hypothèses achirales conduisent à un racémique R/S. Un centre chiral préexistant, un réducteur chiral, une enzyme ou un environnement asymétrique peut les différencier et produire un excès. Il faut écrire le traitement de protonation : l’alcoolate n’est pas déjà l’alcool neutre, et H⁻ ne joue pas le rôle de H⁺ dans l’étape d’addition."),
    exercise("20. Une addition ne signifie pas une substitution d’acyle", "Sup → PC", "carbonyle",
        "Comparer l’attaque d’un nucléophile sur propanone et sur éthanoate d’éthyle. Identifier l’intermédiaire tétraédrique dans les deux cas, puis expliquer pourquoi un départ restaurateur du carbonyle est disponible dans l’ester. Avec CH₃MgBr en excès, donner le produit final à partir de cet ester après hydrolyse.",
        "Dans les deux attaques, Nu vise le C carbonyle et O reçoit les électrons π. Propanone forme un alcoolate (CH₃)₂C(O⁻)Nu ; ses substituants carbonés ne sont pas des groupes partants ordinaires, donc une simple protonation donne l’alcool d’addition. L’ester CH₃COOEt donne CH₃C(O⁻)(Nu)OEt, qui peut reformer C=O en expulsant EtO⁻ : il s’agit d’addition puis élimination, bilan de substitution d’acyle. Avec Nu apporté par CH₃MgBr, cette étape forme propanone, plus réactive que l’ester, puis une seconde addition donne (CH₃)₃CO⁻ avant hydrolyse en tert-butanol. Deux équivalents de carbone nucléophile sont consommés par ester. S’arrêter à la cétone ne constitue pas la voie usuelle avec cet organomagnésien en excès."),
    exercise("21. Trois coupures d’un alcool tertiaire", "Sup", "grignard",
        "La cible est 2-phénylbutan-2-ol, Ph−C(OH)(CH₃)(CH₂CH₃). Donner trois couples cétone/organomagnésien correspondant aux trois coupures C−C autour du C portant OH. Choisir une proposition simple et indiquer traitement final et incompatibilités qui doivent être contrôlées.",
        "Couper la liaison avec Ph donne butan-2-one+PhMgX ; couper avec CH₃ donne propiophénone PhCOCH₂CH₃+CH₃MgX ; couper avec CH₂CH₃ donne acétophénone PhCOCH₃+C₂H₅MgX. Dans chaque cas, le C carbonyle devient le C tertiaire porteur de OH après addition puis hydrolyse/protonation. Le couple acétophénone/éthylmagnésien est une route conceptuellement simple à partir d’espèces courantes. Il faut un milieu et un matériel adaptés anhydres, aucune fonction protonique libre ni autre électrophile incompatible, puis un traitement aqueux terminal distinct. La cible possède un centre stéréogène car les trois groupes carbonés diffèrent ; sans source chirale, les deux faces du carbonyle conduisent normalement à un racémique. Les trois coupures sont possibles conceptuellement, sans garantir les mêmes rendements."),
    exercise("22. Un ester et un proton labile dans le même bilan", "Sup → PC", "grignard",
        "On dispose de 10 mmol d’un ester simple et de 25 mmol de RMgX. Un contaminant protonique HA représente 8 mmol et consomme un équivalent de RMgX par proton. Dans un modèle bilan sans autre réaction, quelle quantité maximale de produit tertiaire l’ester peut-il donner ? Où vont les autres atomes de l’ester ?",
        "Après consommation de HA, il reste 25−8=17 mmol de RMgX disponibles pour l’addition. Un ester simple R′COOR″ demande normalement deux équivalents pour former R′C(OH)R₂ : nmax=min(10,17/2)=8,5 mmol dans ce modèle. Le groupe OR″ est expulsé sous forme alcoolate/sels puis donne R″OH lors du traitement ; le C et O du carbonyle deviennent ceux du centre alcool tertiaire. Le déficit peut laisser aussi des intermédiaires ou des mélanges dans une expérience réelle, donc 8,5 mmol est une borne stœchiométrique et non une prédiction de pureté. L’anhydrie et l’élimination des H labiles évitent une consommation chimique concurrente avant la création C−C. L’hydrolyse terminale est volontairement effectuée après l’addition, pas au départ."),
    exercise("23. Réduire le nitrobenzène : électrons puis quantités", "Sup → PC", "oxydoreduction",
        "Équilibrer en milieu acide PhNO₂→PhNH₂ avec H₂O, H⁺ et e⁻. Un métal Sn est supposé s’oxyder uniquement en Sn⁴⁺. Écrire le bilan pour deux nitrobenzènes. Avec 20 mmol de PhNO₂ et 24 mmol de Sn, déterminer une borne de quantité d’aniline avant protonation acido-basique.",
        "La demi-équation est PhNO₂+6H⁺+6e⁻→PhNH₂+2H₂O. Sn→Sn⁴⁺+4e⁻ ; pour annuler 12 électrons, multiplier la première par 2 et la seconde par 3 : 2PhNO₂+3Sn+12H⁺→2PhNH₂+3Sn⁴⁺+4H₂O. Atomes et charge +12 sont conservés. Le ratio Sn/aniline est 3/2, donc 24 mmol de Sn permettent au plus 16 mmol d’aniline, contre 20 mmol par le nitrobenzène : Sn est limitant dans les hypothèses. En milieu fortement acide, PhNH₂ se protonne en PhNH₃⁺ ; si cette espèce est le produit écrit, ajouter un proton par molécule dans le bilan. Des états d’oxydation métalliques différents ou des réactions parasites exigeraient un autre modèle stœchiométrique."),
    exercise("24. Réduire la cétone en conservant l’ester", "Sup option PC", "oxydoreduction",
        "Une molécule porte une cétone et un ester. Une banque fournit NaBH₄ dans ses conditions usuelles et LiAlH₄ dans un solvant anhydre adapté. Choisir pour produire un hydroxyester puis proposer des observations IR/RMN validant la chimiosélectivité. Pourquoi un alcool tertiaire ne s’oxyde-t-il pas simplement en cétone à squelette conservé ?",
        "NaBH₄ est le choix usuel pour réduire la cétone sans réduire un ester simple dans les conditions fournies ; LiAlH₄ est plus réactif et peut modifier aussi l’ester. L’hydrure attaque le carbonyle de cétone, puis la protonation donne OH. On attend disparition ou forte diminution de sa bande C=O, conservation de la bande d’ester et apparition d’une signature OH ; la RMN doit montrer le nouvel environnement CH−OH si le C porte H et conserver les groupes ester. Une seule tache de CCM ne prouve pas cette connectivité. Un tertiaire R₃COH ne possède aucun H sur ce C : former R₂C=O tout en conservant trois liaisons C−C serait incompatible avec l’octet ; une oxydation forte doit alors rompre ou réorganiser le squelette. La règle d’oxydation douce n’affirme pas une inertie absolue envers tout oxydant."),
    exercise("25. L’ordre nitration/acylation compte", "PC", "aromatique",
        "Construire une route conceptuelle benzène→m-nitroacétophénone avec une banque nitration et acylation de Friedel–Crafts. Comparer les deux ordres possibles. Donner le rôle de l’intermédiaire σ et expliquer pourquoi la direction méta ne suffit pas à conclure que toute transformation aromatique ultérieure est possible.",
        "Acyler d’abord le benzène en acétophénone PhCOCH₃, puis nitrer : le groupe COCH₃ est attracteur −M et désactive les positions ortho/para plus fortement dans les complexes σ, de sorte que méta est favorisé. Nitrer d’abord forme nitrobenzène, fortement désactivé ; une acylation de Friedel–Crafts usuelle n’est alors pas une étape viable à supposer. Dans une SEA, l’attaque forme un complexe σ non aromatique, puis le départ de H⁺ restaure l’aromaticité. L’orientation compare les voies lorsque la réaction est accessible ; l’activation globale compare leurs vitesses au benzène et peut empêcher une réaction donnée. La route doit donc être reconstruite dans le sens direct avec sa banque de conditions, pas validée uniquement par la position finale des substituants."),
    exercise("26. Les halogènes dirigent sans activer", "PC", "aromatique",
        "Comparer les effets de OMe, NO₂ et Br sur une SEA. Les groupes Br et OMe dirigent tous deux ortho/para : sont-ils également activants ? On attribue deux dipôles identiques de module μ à un benzène disubstitué avec angle θ ; exprimer leur somme et dire quelle information manque pour en déduire des proportions de synthèse.",
        "OMe donne par +M et active souvent le noyau ; NO₂ attire par −M et −I, désactive et favorise méta. Br attire par −I tout en possédant une donation de doublet +M : il désactive globalement mais dirige ortho/para. Orientation et activation sont donc des propriétés distinctes. Deux vecteurs de module μ à angle θ ont un module résultant |μtotal|=√(2μ²+2μ²cosθ)=2μ|cos(θ/2)| dans ce modèle vectoriel. Ce calcul décrit un dipôle de structure donnée ; il ne fournit ni les ΔG‡ des voies de formation ni leur réversibilité. Les proportions cinétiques exigent des constantes de vitesse ou barrières, les proportions à l’équilibre des énergies libres des isomères. Mesurer un dipôle peut caractériser une structure sans mesurer sa vitesse de formation."),
    exercise("27. Normaliser une combinaison non orthogonale", "PC — guidé", "orbitales",
        "Deux orbitales réelles normalisées possèdent un recouvrement S=0,30. Normaliser φA+φB et φA−φB, calculer la norme qu’auraient les combinaisons divisées simplement par √2 et discuter le comportement quand S tend vers 1. Les signes des lobes correspondent-ils à des charges ?",
        "L’intégrale de |φA+φB|² est 2+2S=2,60 ; celle de |φA−φB|² vaut 2−2S=1,40. Les combinaisons normalisées sont donc (φA+φB)/√2,60 et (φA−φB)/√1,40, avec dénominateurs 1,612 et 1,183. Les diviser par √2 donnerait des normes carrées 1+S=1,30 et 1−S=0,70, donc une normalisation incorrecte lorsque S≠0. Quand S→1, les fonctions deviennent presque redondantes et le dénominateur antisymétrique tend vers zéro : la base est mal conditionnée, non un générateur physique d’énergie infinie. Les signes représentent des phases d’amplitude ; la densité est |ψ|² et ne porte pas ce signe. Multiplier toute l’orbitale par −1 ne change aucune densité observée."),
    exercise("28. Le butadiène comme problème de valeurs propres", "PC — guidé", "orbitales",
        "On fournit Ej=α+2βcos(jπ/5), j=1..4, β=−2,50 eV pour un modèle Hückel du butadiène. Donner les niveaux relatifs à α, remplir quatre électrons, calculer l’écart HO/BV et une longueur d’onde associée hc=1240 eV·nm. Cette estimation est-elle un spectre UV expérimental complet ?",
        "Les cosinus donnent les facteurs 1,618 ; 0,618 ; −0,618 ; −1,618. Puisque β<0, les niveaux croissants sont α−4,045, α−1,545, α+1,545 et α+4,045 eV. Quatre électrons occupent les deux premiers avec deux électrons par orbitale ; HO est le deuxième, BV le troisième. Leur écart vaut 3,090 eV et λ≈1240/3,090=401 nm si l’on assimile cet écart à une transition permise. Il s’agit d’une illustration de remplissage et de dimensionnement, non d’une valeur tabulée du butadiène réel : le β choisi, les interactions électroniques, la géométrie, les règles de transition et la relaxation ne sont pas décrits complètement. La connectivité et l’orthonormalité de la base doivent être déclarées avant cette diagonalisation."),
    exercise("29. Deux barrières et deux stabilités", "PC", "cinetique",
        "À 298 K, deux voies irréversibles de mêmes préfacteurs ont ΔG‡A=60 et ΔG‡B=65 kJ·mol⁻¹. Calculer la fraction initiale de A. Si les produits s’interconvertissent ensuite et B est plus stable de 8 kJ·mol⁻¹, calculer la fraction de B à l’équilibre. Donner les hypothèses supplémentaires du second résultat.",
        "RT=8,314×298/1000≈2,478 kJ·mol⁻¹. kA/kB=exp((65−60)/RT)≈7,52 ; parmi les produits nouvellement formés, fA=7,52/(1+7,52)=88,3 %. À l’équilibre, GB−GA=−8 kJ·mol⁻¹ donc B/A=exp(8/RT)≈25,2 et fB≈96,2 %. La composition finale oppose ainsi préférence cinétique pour A et préférence thermodynamique pour B. Le second calcul exige des produits capables de s’interconvertir ou de retourner à un réseau commun, assez de temps, température constante et activités comparables dans l’état standard choisi. Chauffer ou attendre ne garantit pas l’équilibre si la barrière de retour reste inaccessible. Une catalyse modifie l’approche de cet équilibre sans changer le rapport thermodynamique à T fixée."),
    exercise("30. Une expérience qui identifie l’énergie d’activation", "Sup option PC → PC", "cinetique",
        "Une constante de même ordre passe de k₁=0,010 à k₂=0,040 lorsque T passe de 298 à 318 K. Utiliser Arrhenius à préfacteur constant pour estimer Ea. Expliquer pourquoi comparer les logarithmes d’une constante de premier ordre et d’une constante de second ordre serait une opération différente, et proposer un contrôle expérimental.",
        "ln(k₂/k₁)=Ea/R(1/T₁−1/T₂). Ici ln4=1,386 et 1/298−1/318≈2,110×10⁻⁴ K⁻¹ ; Ea≈8,314×1,386/(2,110×10⁻⁴)=54,6 kJ·mol⁻¹. Le ratio est sans dimension parce que k₁ et k₂ ont le même type et les mêmes unités. Une constante s⁻¹ ne peut être rapportée sans précision à une constante L·mol⁻¹·s⁻¹ : il faudrait définir les concentrations et les constantes apparentes pertinentes. Plusieurs températures permettent de tester une droite ln k contre 1/T et d’estimer une incertitude. Un changement de mécanisme, de solubilité ou de régime de diffusion peut courber cette droite, donc deux points ne démontrent pas la constance de Ea sur une large plage."),
    exercise("31. Une formule qui ne suffit pas à une identité", "Sup", "formule",
        "Une espèce neutre a formule C₈H₈O₂. Calculer son indice d’insaturation. Proposer deux connectivités incluant un cycle benzénique et un carbonyle, puis indiquer quelles différences IR/RMN permettent de choisir entre benzoate de méthyle et acide phénylacétique. Préciser quel pic attendre pour [M+H]⁺ si M nominal vaut 136.",
        "IHD=(2×8+2−8)/2=5 : benzène utilise quatre unités, C=O une. Benzoate de méthyle PhCOOCH₃ et acide phénylacétique PhCH₂CO₂H possèdent cette formule. Le premier donne un OCH₃ singulet 3H et une fonction ester ; le second un CH₂ benzylique 2H et un proton acide échangeable, avec une bande OH carboxylique très large. Tous deux ont cinq H aromatiques : ce seul massif ne les distingue pas. Un ion [M+H]⁺ de charge +1 se trouve nominalement à m/z=137, pas 136, tandis qu’un ion moléculaire M⁺· serait à 136. Il faut donc nommer la méthode d’ionisation et ne pas assimiler masse moyenne, masse exacte et m/z. Ces connectivités respectent les huit C et l’IHD, mais les données supplémentaires font l’identité."),
    exercise("32. Compter les halogènes par les enveloppes isotopiques", "Sup → PC", "formule",
        "Une enveloppe M, M+2, M+4 est proche de 9:6:1 ; une autre proche de 1:2:1. Interpréter avec les approximations abondance Cl=3:1 et Br=1:1. Pour une molécule contenant un Cl et un Br, calculer l’enveloppe prévue. Que manque-t-il pour lire toute une spectrométrie de masse réelle ?",
        "Deux Cl donnent (3+x)²=9+6x+x² : les coefficients 9:6:1 correspondent aux nombres de noyaux lourds 0,1,2. Deux Br donnent (1+x)²=1+2x+x², donc 1:2:1. Un Cl et un Br donnent (3+x)(1+x)=3+4x+x², soit 3:4:1. L’écart de masse est environ 2 unités par isotope lourd dans cette lecture nominale. Les sommes normalisent les intensités si l’on veut des fractions : pour le mélange Cl/Br, 3/8,4/8,1/8. Une enveloppe réelle contient aussi ¹³C, autres isotopes, résolution finie, fragments pouvant perdre un halogène et parfois plusieurs ions ; le motif est un indice de composition de l’ion étudié, pas une attribution unique de structure moléculaire."),
    exercise("33. Polarimétrie et excès énantiomérique", "Sup", "stereo",
        "Pour un couple d’énantiomères, l’échantillon pur R tourne de +10,0° dans les conditions de mesure. Un mélange ne contenant que R et S, de même concentration totale et même trajet, tourne de +3,0°. Déterminer ee et proportions. La configuration R serait-elle toujours positive ? Reprendre si une impureté achirale dilue la concentration sans correction.",
        "À composition et réponse linéaires, αmélange=(xR−xS)αR,pur. Avec xR+xS=1, xR−xS=0,30, donc ee=30 %, xR=0,65 et xS=0,35. Le signe + indique seulement l’énantiomère majoritaire pour la référence donnée ; R ne signifie pas dextrogyre en général. Si une impureté achirale diminue la concentration réelle en analyte mais que l’on compare à une référence plus concentrée, une rotation plus faible peut venir de la dilution autant que d’un ee plus faible. Il faut connaître concentration, longueur du trajet, solvant, température, longueur d’onde et pureté avant d’en déduire les proportions. Le laboratoire paramètre une rotation de référence explicitement et ne fabrique pas une relation universelle R=+."),
    exercise("34. Deux centres ne donnent pas toujours quatre molécules", "Sup", "stereo",
        "Compter les stéréoisomères de l’acide tartrique HO₂C−CH(OH)−CH(OH)−CO₂H. Classer les paires et expliquer pourquoi la forme (R,S) peut être achirale. Comparer à une chaîne dissymétrique ayant deux centres indépendants et des extrémités différentes.",
        "Les configurations formelles sont (R,R), (S,S), (R,S) et (S,R), mais les extrémités identiques permettent la superposition de (R,S) et (S,R) : elles désignent la même forme méso. Il y a donc trois stéréoisomères. (R,R)/(S,S) forment une paire d’énantiomères ; chacun est diastéréoisomère du méso. La forme méso possède des centres stéréogènes mais sa symétrie rend l’image miroir superposable : centres stéréogènes et chiralité globale ne sont pas synonymes. Dans une chaîne dissymétrique à deux centres sans symétrie ni autre contrainte, 2²=4 isomères peuvent subsister, en deux paires miroir. Une projection doit être accompagnée d’une vraie opération de rotation/symétrie, car permuter arbitrairement un seul couple de groupes inverserait un centre et ne serait pas une rotation globale."),
    exercise("35. Anti et gauche : ne pas oublier deux minima", "Sup → PC", "conformeres",
        "Pour un modèle discret du butane, Ganti=0 et deux états gauche ont chacun ΔG=3,8 kJ·mol⁻¹. Calculer Panti et Pgauche total à 298 K. Refaire la limite T très élevée dans ce modèle. Pourquoi un modèle intégrant toute la courbe de torsion peut-il donner une autre population ?",
        "À 298 K, RT=2,478 kJ·mol⁻¹ et w=exp(−3,8/RT)≈0,216. Z=1+2w≈1,432, donc Panti=1/Z≈69,9 % et Pgauche,total=2w/Z≈30,1 %, chaque gauche valant environ 15,1 %. Oublier le facteur 2 surestimerait anti. Dans la limite T→∞ de ces seuls trois états, les poids deviennent égaux : anti→1/3 et gauche total→2/3. Une intégration d’exp[−V(θ)/RT] sur l’angle compte la largeur de chaque puits, les zones entre minima et les corrections que ΔG peut déjà inclure ; elle n’est pas identique à trois états ponctuels. À haute température, le modèle discret peut aussi perdre sa pertinence. La dégénérescence et la nature énergie/énergie libre doivent donc être déclarées avant la moyenne statistique."),
    exercise("36. Le basculement d’une chaise conserve la face", "Sup → PC", "conformeres",
        "Un méthylcyclohexane a ΔGax−eq=7,5 kJ·mol⁻¹ à 298 K dans le modèle. Calculer le rapport axial/équatorial et la population équatoriale. Lors du basculement, CH₃ axial haut devient-il équatorial haut ou bas ? Expliquer la différence entre conformation et configuration cis/trans pour un cyclohexane disubstitué.",
        "ax/eq=exp(−7,5/2,478)≈0,0485 ; Peq=1/(1+0,0485)≈95,4 %. Ce rapport compare deux chaises de dégénérescence égale dans le modèle, et non deux chemins de réaction. Lors du basculement, un CH₃ axial haut devient équatorial haut : axial/équatorial change, haut/bas demeure. Pour un cycle disubstitué, deux groupes sur la même face restent cis après basculement, deux faces opposées restent trans ; les arrangements axiaux et équatoriaux associés dépendent des positions 1,2/1,3/1,4. Une barrière de basculement gouverne la vitesse de changement mais ne doit pas être ajoutée aux ΔG des minima pour calculer la population d’équilibre. Ce distinguo sert ensuite aux E2 trans-diaxiales."),
    exercise("37. Isotope et ressort : un nombre d’onde prédit", "Sup option PC", "ir",
        "Une bande OH est à 3400 cm⁻¹. Avec mO=16u, mH=1u et mD=2u, estimer la bande OD en gardant la même constante de force. Déterminer la fréquence de OH avec c=3,00×10¹⁰ cm·s⁻¹ et dire pourquoi l’intensité d’une bande ne se déduit pas de la seule masse réduite.",
        "μOH=16/17u≈0,941u ; μOD=32/18u≈1,778u. Le rapport est ṽOD/ṽOH=√(μOH/μOD)≈0,728, d’où ṽOD≈2474 cm⁻¹. La fréquence OH vaut ν=cṽ=3,00×10¹⁰×3400=1,02×10¹⁴ s⁻¹. La constante de force est supposée identique ; liaisons hydrogène et couplages de modes peuvent modifier cette estimation. L’activité et l’intensité IR dépendent de la variation du moment dipolaire avec la coordonnée normale, pas seulement de μ et k. Une liaison qui vibre n’absorbe pas nécessairement de façon intense en IR. L’unité de c doit correspondre au cm⁻¹ pour éviter un facteur 100 ; employer c en m·s⁻¹ impose de convertir le nombre d’onde en m⁻¹."),
    exercise("38. Additionner les absorbances, pas les transmittances", "Sup option PC", "ir",
        "Deux espèces indépendantes donnent à un nombre d’onde des absorbances A₁=0,20 et A₂=0,35, à la même longueur de trajet. Déterminer la transmittance du mélange, puis son évolution si les deux concentrations doublent. Comment une réduction cétone→alcool pourrait-elle être suivie sans conclure uniquement d’une bande OH ?",
        "L’absorbance totale vaut A=0,20+0,35=0,55, donc T=10^(−0,55)≈0,282, soit 28,2 %. Après doublement des concentrations, A=1,10 et T≈0,0794, soit 7,94 %. Ce sont les absorbances qui s’additionnent ; additionner deux pourcentages de transmittance n’a pas de sens pour les transmissions successives équivalentes. Pour suivre une réduction, observer la décroissance d’une bande C=O identifiée et l’apparition de signatures d’alcool, avec un étalonnage si l’on veut une quantité. Une bande OH peut aussi provenir d’eau ou d’un alcool solvant ; la RMN et un contrôle de pureté complètent la conclusion. Dans le TP, les gaussiennes sont calculées et ne sont pas vendues comme des spectres mesurés de référence."),
    exercise("39. Éthanoate ou propanoate ?", "Sup option PC", "rmn",
        "Une espèce C₄H₈O₂ donne un singulet 3H à 2,05 ppm, un triplet 3H à 1,25 ppm et un quartet 2H à 4,12 ppm, les deux derniers avec J=7,2 Hz. Proposer la structure. Combien d’environnements ¹³C attend-on ? À 400 MHz, quel espacement en ppm sépare les raies du quartet ?",
        "Triplet 3H et quartet 2H avec même J forment un groupe CH₂CH₃. Le CH₂ à 4,12 ppm est lié à O ; le singulet CH₃ vers 2,05 ppm est un méthyle acyle sans H voisin couplant à travers le carbonyle dans ce modèle. La structure est CH₃COOCH₂CH₃, éthanoate d’éthyle. Ses quatre C sont distincts : C=O, CH₃ acyle, OCH₂ et CH₃ terminal donnent quatre environnements ¹³C découplés. L’espacement d’un quartet est J/ν₀=7,2/400=0,018 ppm ; le groupe entier span trois espacements, 0,054 ppm, dans le premier ordre. Le propanoate de méthyle aurait un OCH₃ singulet vers 3,7 ppm et son CH₂ à côté de C=O vers 2,3 ppm : ses intégrales 3/2/3 seules ne suffisent pas à le distinguer."),
    exercise("40. Quantifier un mélange par deux singulets", "Sup option PC → PC", "rmn",
        "Un mélange contient propanone et acide éthanoïque. Le singulet de propanone (6H) intègre 18 unités et le CH₃ acide (3H) 12 unités. Déterminer les fractions molaires si l’acquisition est quantitative. Puis considérer deux protons à Δδ=0,05 ppm et J=8 Hz : comparer Δν/J à 60 et 600 MHz.",
        "Les quantités sont proportionnelles aux intégrales divisées par les H responsables : npropanone∝18/6=3 et nacide∝12/3=4. Les fractions molaires valent donc 3/7≈42,9 % et 4/7≈57,1 %, pas 60/40 issus des intégrales brutes. L’acquisition doit permettre relaxation et réponse adaptées ; une superposition de pics empêcherait cette lecture. À 60 MHz, Δν=0,05×60=3 Hz et Δν/J=0,375 ; à 600 MHz, Δν=30 Hz et le rapport vaut 3,75. Le champ plus élevé améliore la séparation en Hz mais ce dernier rapport n’est encore pas « très grand » : la règle n+1 du premier ordre peut demeurer insuffisante. Une simulation de raies de premier ordre doit donc annoncer ce diagnostic plutôt que prétendre résoudre un système fortement couplé."),
    exercise("41. Choisir un éluant qui sépare réellement", "Sup TP", "ccm",
        "Trois éluants donnent respectivement RfA/RfB : 0,05/0,10 ; 0,35/0,60 ; 0,85/0,90. Choisir pour séparer, sachant un front à 60 mm et des taches de largeur 4 mm. Calculer Δd pour chacun. Pourquoi deux taches à même Rf ne prouvent-elles pas une identité moléculaire ?",
        "Les écarts Δd=ΔRf×60 mm valent 3 mm, 15 mm et 3 mm. Le deuxième éluant sépare nettement deux taches de largeur 4 mm, avec des Rf ni au dépôt ni au front ; les deux autres peuvent superposer les taches malgré une migration globale différente. Le choix doit aussi garder une révélation efficace et une charge de dépôt raisonnable. Une même valeur de Rf est une propriété du couple molécule/éluant/plaque et peut être partagée par des structures différentes. Une co-tache référence+inconnu et un autre éluant apportent des tests utiles, mais IR/RMN ou une autre caractérisation restent nécessaires. L’intensité ne donne pas directement la pureté sans réponse révélatrice et étalonnage ; une tache de produit unique peut cacher plusieurs composés coéluants."),
    exercise("42. Suivre une réaction par prélèvements raisonnés", "Sup TP", "ccm",
        "Pendant une synthèse, une tache de réactif baisse et une tache de produit apparaît. Proposer une comparaison par CCM qui permet de discuter la fin de réaction. Un échantillon continue de réagir après prélèvement : quel biais s’introduit ? Peut-on calculer un rendement isolé à partir d’une disparition visuelle ?",
        "Déposer sur une même plaque une référence du réactif, une du produit si disponible, plusieurs prélèvements à des temps connus et éventuellement une co-tache. Choisir un éluant séparateur et une charge comparable. Si l’aliquote réagit encore, son temps de mesure n’est plus son temps de prélèvement : il faut prévoir une trempe, dilution ou condition d’arrêt adaptée, puis vérifier que cette opération ne crée pas elle-même de produit. La disparition visuelle signifie au mieux que le réactif descend sous le seuil de détection de cette révélation ; elle ne prouve pas conversion exactement 100 %. Le rendement isolé y=nproduit,pur/nthéorique demande récupération, masse ou quantité, identité et pureté. Une CCM forme un outil de suivi et de choix d’opération, à compléter par un bilan quantitatif indépendant."),
    exercise("43. Un volume total, une ou deux extractions", "Sup TP", "extraction",
        "Une substance a D=5 entre phase organique et aqueuse. Vaq=100 mL et le volume total de solvant neuf est 100 mL. Comparer une extraction et deux extractions de 50 mL. Démontrer le bilan d’une extraction puis indiquer les hypothèses qui empêchent une optimisation aveugle avec un nombre arbitrairement grand de contacts.",
        "À l’équilibre Corg=DCaq et n₀=CaqVaq+DCaqVorg. La fraction aqueuse est q=Vaq/(Vaq+DVorg). Un contact de 100 mL laisse 100/(100+500)=1/6=16,67 % ; deux de 50 mL laissent [100/(100+250)]²=(2/7)²=8,16 %. Les récupérations sont donc 83,33 % et 91,84 %. Les deux contacts utilisent du solvant neuf et atteignent l’équilibre à volumes constants. Des volumes très petits rendent pertes de transfert, solubilité mutuelle, émulsions, temps de séparation et saturation non négligeables ; le modèle idéal ne fournit pas seul le meilleur protocole réel. On doit aussi vérifier que le produit n’est ni dégradé ni ionisé différemment entre contacts et que D demeure constant."),
    exercise("44. Séparer un acide par un pH maintenu", "Sup TP → PC", "extraction",
        "Un acide HA a pKa=4,5 en eau et P=10 pour sa forme neutre. Le milieu aqueux est tamponné à pH=6,5, puis dans une autre étape à pH=2,5. Calculer D aux deux pH et la fraction extraite avec volumes égaux. Une substance neutre de P=10 accompagne-t-elle la même variation ?",
        "D=P/[1+10^(pH−pKa)]. À pH=6,5, D=10/101≈0,0990 et la fraction organique pour volumes égaux est D/(1+D)≈9,01 %. À pH=2,5, D=10/1,01≈9,901 et la fraction vaut ≈90,83 %. Le changement de pH permet de garder HA ionisé en phase aqueuse, puis de le régénérer sous forme neutre extractible. Une substance neutre de P=10 conserve, dans le modèle, une fraction organique 10/11=90,91 % à ces deux pH ; cette différence permet une séparation. Les calculs supposent seulement HA neutre en organique, équilibre atteint et pH effectivement maintenu. Sans tampon assez capable, le transfert de protons et les quantités d’acide changent le pH et imposent un bilan couplé."),
    exercise("45. Déplacer l’équilibre sans changer sa constante", "Sup", "esterification",
        "Un modèle homogène idéal d’estérification possède K=4, avec aucune eau ni ester initiaux. Calculer la conversion pour 1 mol d’acide+1 mol d’alcool, puis 1 mol d’acide+5 mol d’alcool. Une catalyse acide change-t-elle K ? Que devient le calcul si l’eau est un solvant en très grand excès ?",
        "Avec stocks 1/1, K=x²/(1−x)²=4, donc x=2/3 mol, soit 66,67 % de l’acide. Avec stocks 1/5, K=x²/[(1−x)(5−x)]=4 : 3x²−24x+20=0. La racine physique est x=(24−√336)/6≈0,94495 mol ; l’autre dépasse le stock limitant. L’excès d’alcool élève la conversion à 94,49 % dans ce modèle sans changer K à T fixée. Le catalyseur accélère aller et retour et ne modifie pas l’équilibre. Si l’eau est solvant en excès, son activité est souvent prise proche de 1 et les activités des solutés suivent un autre choix de standard : on ne réutilise pas aveuglément x² comme produit ester/eau du mélange initial anhydre."),
    exercise("46. Saponifier puis acidifier : deux étapes de bilan", "Sup → PC", "esterification",
        "On fait réagir 12 mmol d’un ester avec 10 mmol de HO⁻ dans un modèle de saponification complète de l’équivalent limitant. Déterminer ester restant, carboxylate et alcool formés. Combien de H⁺ faut-il au minimum pour convertir le carboxylate en acide, en négligeant les autres bases présentes ?",
        "Le bilan RCOOR′+HO⁻→RCOO⁻+R′OH consomme les réactifs 1:1. HO⁻ est limitant ; l’avancement est 10 mmol. Restent 2 mmol d’ester, se forment 10 mmol de carboxylate et 10 mmol d’alcool. La conversion de l’ester vaut 10/12=83,33 % dans ce modèle. Acidifier le carboxylate demande RCOO⁻+H⁺→RCOOH, au moins 10 mmol de H⁺, puis un milieu suffisamment acide pour favoriser la forme neutre selon son pKa. Dans une manipulation réelle, un excès de HO⁻ ou d’autres bases consommerait aussi l’acide. Le produit de la saponification est un sel carboxylate ; le nommer directement acide carboxylique sans le traitement final manquerait une étape de séparation souvent essentielle."),
    exercise("47. L’amine peut aussi être la base", "PC", "acylation",
        "Une banque décrit RCOCl+2R′NH₂→RCONHR′+R′NH₃⁺Cl⁻. On mélange 10 mmol de chlorure d’acyle et 14 mmol d’amine sans autre base. Calculer la quantité théorique dans ce modèle. Refaire avec 10 mmol d’amine et au moins 10 mmol d’une base externe adaptée. Identifier la fonction de chaque équivalent.",
        "Sans base externe, une molécule d’amine forme la liaison amide et une autre capte le proton équivalent à HCl. La borne est min(10,14/2)=7 mmol d’amide ; l’amine limite le bilan 1:2. Avec une base externe adaptée, l’amine peut être consacrée à l’acylation : 10 mmol d’amine et 10 mmol d’acyle permettent 10 mmol d’amide, tandis que la base piège 10 mmol de protons. Ce modèle n’affirme pas que chaque expérience sans base s’arrête précisément à 7 mmol : solubilité, transferts et acidité peuvent compliquer la distribution. Il expose pourquoi le rôle nucléophile et le rôle base sont distincts et pourquoi il faut comptabiliser les deux. Le mécanisme passe par attaque de l’amine, intermédiaire tétraédrique, départ de Cl⁻ puis déprotonation."),
    exercise("48. Une N-acylation emblématique : le paracétamol", "PC", "acylation",
        "À partir de p-aminophénol, on utilise une banque d’acylation sélective conduisant au paracétamol. Nommer la fonction créée et celle conservée. Proposer des données de caractérisation prouvant la cible plutôt qu’un produit O-acétylé. Le p-aminophénol et le paracétamol ont masses molaires 109,13 et 151,16 g·mol⁻¹ : quelle masse théorique vient de 2,00 g de réactif limitant ?",
        "N-acétyler le NH₂ forme une amide −NHCOCH₃ tandis que le OH phénolique est conservé. Un produit O-acétylé posséderait un ester et une amine libre : la connectivité diffère malgré une acétylation au même nombre d’atomes ajouté. Il faut comparer IR (amide, NH et OH), RMN (CH₃ acyle, environnements aromatiques, protons échangeables avec prudence), et éventuellement une référence de point de fusion/pureté ; une masse ou une CCM seules ne suffisent pas. Le stock est 2,00/109,13=18,33 mmol ; la masse théorique 1:1 vaut 0,01833×151,16≈2,77 g. La chimiosélectivité est une propriété des conditions fournies et doit être observée ; elle n’est pas décrétée simplement parce qu’une molécule porte deux nucléophiles."),
    exercise("49. Protéger n’est utile que si la suite est compatible", "Sup option PC", "protection",
        "Une route exige de conserver un carbonyle pendant une étape organomagnésienne sur un autre site. La banque permet sa conversion sélective en acétal, stable dans l’étape suivante. Or le mélange de protection contient eau et acide. Proposer l’ordre des opérations et identifier ce qui arriverait si RMgX était ajouté immédiatement à ce milieu.",
        "La séquence est protéger le carbonyle choisi par acétalisation sous conditions adaptées, isoler ou préparer un milieu débarrassé d’eau et d’acide, réaliser l’étape organomagnésienne en milieu anhydre, effectuer son traitement terminal puis hydrolyser l’acétal en milieu aqueux acide compatible avec le produit. RMgX ajouté au mélange de protection réagit avec H labiles et eau : RMgX+HA→RH+sels, avant la création C−C visée. Une protection correctement dessinée ne suffit donc pas : les conditions résiduelles comptent. Il faut aussi vérifier que les deux carbonyles de départ peuvent être discriminés et que la déprotection n’altère pas le nouveau produit. Cette route dépend d’une banque déclarant la sélectivité de protection ; on ne peut la supposer pour toute molécule à plusieurs carbonyles."),
    exercise("50. Le coût de trois opérations supplémentaires", "Sup option PC → PC", "protection",
        "Une voie protégée comporte des rendements isolés 90 %, 85 % et 95 %. Une autre voie directement compatible donne 80 %. Comparer les rendements globaux et le produit obtenu depuis 10 mmol de cible théorique. Peut-on décider uniquement par ces nombres si la voie directe a un problème de sélectivité non mesuré ?",
        "La voie protégée donne y=0,90×0,85×0,95=0,72675, soit 72,68 % ; depuis 10 mmol théoriques on isole 7,2675 mmol. La voie directe à 80 % donne 8,0 mmol, donc davantage si les deux rendements concernent bien le même produit pur et des périmètres comparables. Les pertes se multiplient, elles ne se moyennent pas. Cependant un « 80 % » de mélange non caractérisé n’est pas comparable à 72,68 % de cible pure : la sélectivité et la purification peuvent modifier le bilan. La décision doit intégrer compatibilité, identité, pureté, coût, nombre d’isolements et consommation de solvants. Une protection ajoute des déchets, mais évite parfois une réaction destructrice incontournable ; une optimisation suppose une alternative concrètement valide."),
    exercise("51. Construire la chalcone en suivant les atomes", "PC", "aldol",
        "Nommer donneur et accepteur pour former la chalcone PhCOCH=CHPh depuis acétophénone et benzaldéhyde. Dessiner le β-hydroxycarbonyle puis l’eau éliminée. Pourquoi l’absence d’Hα du benzaldéhyde simplifie-t-elle la réaction croisée ? Calculer la masse théorique depuis 10 mmol de chaque partenaire avec Mchalcone=208,26 g·mol⁻¹.",
        "L’acétophénone PhCOCH₃ possède des Hα et fournit l’énolate carboné ; le benzaldéhyde PhCHO sans Hα est l’accepteur électrophile. L’attaque forme PhCOCH₂CH(O⁻)Ph puis PhCOCH₂CH(OH)Ph après protonation, β-hydroxycétone. La déshydratation enlève un Hα et le OHβ dans le bilan net d’une eau pour produire PhCOCH=CHPh. Le benzaldéhyde ne forme pas un énolate par déprotonation α, ce qui réduit les possibilités d’auto-aldolisation et de croisements, sans supprimer toute réaction parasite. Le bilan cible est 1:1 ; 10 mmol permettent au plus 0,010×208,26=2,0826 g de chalcone. Il faut encore mesurer rendement, configuration et pureté ; le produit E souvent favorisé n’est pas un pourcentage imposé par la formule seule."),
    exercise("52. Pourquoi deux carbonyles énolisables compliquent une aldol", "PC", "aldol",
        "Mélanger sans sélection deux aldéhydes A et B tous deux énolisables. Énumérer les couples donneur/accepteur possibles sans détailler leurs régioisomères. Proposer deux stratégies réduisant cette multiplicité, puis expliquer pourquoi une déshydratation ne doit pas être incluse automatiquement dans toute aldolisation.",
        "Les couples sont A/A, B/B, A/B et B/A, donc deux auto- et deux croisements distincts avant même de considérer plusieurs sites α et la stéréochimie. Un énolate préformé de A, puis l’addition contrôlée de B, peut rendre A donneur privilégié si la banque de conditions le permet. Choisir un accepteur non énolisable, par exemple benzaldéhyde, supprime aussi une source d’énolate ; un autre levier est la dilution ou une réaction intramoléculaire adaptée. Le produit initial est un β-hydroxycarbonyle ; la crotonisation demande des conditions de déshydratation et peut être réversible ou concurrencée. Le bilan aldolisation n’élimine pas d’eau alors que le bilan condensation complète en élimine une. Identifier l’étape observée est nécessaire pour lire une masse molaire et un spectre corrects."),
    exercise("53. Addition 1,2 ou 1,4 : des cibles différentes", "PC", "michaelwittig",
        "Un accepteur est CH₃COCH=CH₂. Comparer les connectivités finales après addition protonée d’un Nu carboné en 1,2 et en 1,4. Où reste le carbonyle ? Quel type de donneur énolate pourrait favoriser une addition de Michael dans une banque adaptée ? Proposer une caractérisation discriminante.",
        "En 1,2, Nu attaque le C du carbonyle : le produit après protonation est CH₃C(OH)(Nu)CH=CH₂, un alcool allylique, avec C=C conservée et C=O transformée. En 1,4, Nu se fixe sur le Cβ terminal ; les déplacements π donnent un énolate puis la protonation/tautomérie conduit à CH₃COCH₂CH₂Nu, carbonyle conservé et C=C saturée. Un énolate stabilisé, comme celui d’un β-dicarbonyle, est un donneur fréquent de Michael dans les conditions appropriées ; « énolate » ne garantit cependant pas universellement 1,4. En IR/RMN, le premier produit perd C=O et garde les protons vinyliques, tandis que le second garde C=O et perd les signatures de l’alcène de l’accepteur. La nouvelle liaison doit être localisée avant d’invoquer une règle dur/mou."),
    exercise("54. Wittig : choisir le carbone introduit", "PC", "michaelwittig",
        "Proposer un ylure transformant benzaldéhyde en styrène puis en PhCH=CHCH₃. Écrire les produits secondaires du bilan de Wittig. Pour le second alcène, quelles configurations sont possibles et pourquoi une tendance Z d’un ylure non stabilisé n’est-elle pas une composition chiffrée universelle ?",
        "PhCHO+Ph₃P=CH₂→PhCH=CH₂+Ph₃P=O construit le styrène ; le carbone terminal porte deux H, donc aucune configuration E/Z. Pour PhCH=CHCH₃, employer l’ylure Ph₃P=CHCH₃ : le carbone de l’ylure porte H et CH₃, celui de l’aldéhyde H et Ph, permettant E et Z. L’oxygène du carbonyle devient celui de Ph₃P=O ; le nombre de C introduit se lit directement sur l’ylure. Un ylure non stabilisé présente souvent une préférence Z dans certains protocoles, mais formation de l’ylure, contre-ions, sels, solvant et température modifient les voies. La banque doit préciser des conditions et, si un ratio est nécessaire, fournir une sélectivité mesurée ou un modèle déclaré. Une règle qualitative ne vaut pas un rendement ni un rapport exact."),
    exercise("55. Les six centres d’une Diels–Alder", "PC", "dielsalder",
        "Numéroter C1–C4 d’un diène et C5–C6 d’un diénophile. Donner les nouvelles liaisons et la liaison π restante après [4+2], puis discuter un diène bloqué s-trans et le devenir de deux substituants cis sur C5/C6. Que faut-il ajouter pour discuter endo/exo d’un adduit bicyclique ?",
        "Une orientation choisie forme C1−C6 et C4−C5, transforme les anciennes liaisons π terminales et laisse C2=C3 ; la seconde orientation échange C5/C6 si les partenaires sont dissymétriques. Le cycle C1−C2−C3−C4−C5−C6 compte six centres, deux nouvelles liaisons σ et une π résiduelle. Un diène bloqué s-trans ne rapproche pas les extrémités dans la géométrie concertée ordinaire : un bon écart HO/BV ne supprime pas cette contrainte. Des substituants cis du diénophile gardent leur relation cis, par conservation de sa stéréochimie. Endo/exo compare ensuite leur orientation vis-à-vis du pont de l’adduit bicyclique, distincte de cis/trans ; il faut dessiner le pont et les groupes π attracteurs avant de discuter une préférence cinétique."),
    exercise("56. Endo cinétique ne veut pas dire exo impossible", "PC", "dielsalder",
        "Un modèle irréversible à 298 K donne une barrière endo plus basse de 3 kJ·mol⁻¹ que l’exo, avec mêmes préfacteurs. Déterminer le rapport et les fractions. Dans un autre modèle réversible, exo est plus stable de 2 kJ·mol⁻¹ : déterminer la composition d’équilibre et les conditions sous lesquelles elle remplace la première.",
        "En cinétique, kendo/kexo=exp(3/2,478)≈3,36, donc fendo≈3,36/4,36=77,1 % et fexo≈22,9 %. À l’équilibre du deuxième modèle, Gexo−Gendo=−2 kJ·mol⁻¹, donc exo/endo=exp(2/2,478)≈2,24 : fexo≈69,2 % et fendo≈30,8 %. Les deux compositions répondent à deux situations différentes ; on ne les moyenne pas. L’équilibre exige une réversibilité accessible, une interconversion via un réseau commun et assez de temps à température contrôlée. Un adduit endo peut rester piégé si la rétro-Diels–Alder est trop lente. Ces nombres sont des conséquences d’énergies déclarées, non des valeurs universelles de cyclopentadiène/anhydride maléique dans n’importe quel solvant."),
    exercise("57. Aspirine : masse humide et pureté", "Sup TP → PC", "retrosynthese",
        "Une synthèse 1:1 utilise 5,00 g d’acide salicylique, M=138,12 g·mol⁻¹, agent acylant en excès. Elle isole 4,80 g d’un solide à 95 % massique d’aspirine, M=180,16 g·mol⁻¹. Calculer rendement apparent et rendement en produit pur. Proposer une cause de surestimation de masse et une preuve de la fonction acétylée.",
        "nlim=5,00/138,12=0,03620 mol ; mth=0,03620×180,16=6,522 g. Le rendement apparent sur masse brute est 4,80/6,522≈73,6 %. La masse de produit pur est 0,95×4,80=4,56 g, d’où ypur≈69,9 %. Eau ou solvant résiduel, réactif coprécipité et sels peuvent augmenter la masse sans augmenter l’aspirine. La cible est une O-acétylation du OH phénolique de l’acide salicylique, conservant le carboxylique ; IR/RMN, comparaison à une référence et contrôle de pureté doivent confirmer cette connectivité. L’excès d’agent acylant ne rend pas automatiquement la conversion et la récupération complètes : le rendement mesure la chaîne de réaction, isolation et purification."),
    exercise("58. Économie d’atomes et PMI racontent deux choses", "PC", "retrosynthese",
        "Le bilan conceptuel aspirinique salicylique+anhydride éthanoïque→aspirine+acide éthanoïque utilise masses molaires 138,12,102,09,180,16 et60,05. Calculer l’économie d’atomes. Une opération consomme au total 240 g d’entrées pour 4,56 g de produit pur ; calculer PMI et E-factor pour un bilan complet au même périmètre. Comparer ces indicateurs.",
        "L’équation équilibrée conserve 138,12+102,09=180,16+60,05=240,21 g pour une mole de cible. L’économie d’atomes vaut 180,16/240,21≈75,0 %. Elle repose sur l’équation, pas sur la récupération réelle ni les litres de solvants. PMI=240/4,56≈52,63 g/g. Si toutes les autres entrées deviennent déchets et que le bilan est complet, E-factor=(240−4,56)/4,56=51,63=PMI−1. Il faut annoncer si eau et solvants recyclés sont inclus ; changer le périmètre modifie ces nombres. Une réaction à 75 % d’économie d’atomes peut donc avoir un PMI élevé. Réduire volume de solvant, pertes de purification et excès de réactif constitue une autre optimisation que choisir une équation plus atomique."),
    exercise("59. Carothers : une stœchiométrie presque égale", "PC", "polymeres",
        "Utiliser Xn=(1+r)/(1+r−2rp), r≤1, pour une polymérisation par étapes bifonctionnelle. Comparer r=1,p=0,99 puis r=0,98,p=0,99. Donner la limite p→1 pour r=0,98 et expliquer quelle pureté est concernée par ce calcul.",
        "Pour r=1, Xn=2/(2−2p)=1/(1−p)=100 à p=0,99. Pour r=0,98, Xn=1,98/(1,98−2×0,98×0,99)=1,98/0,0396=50. À conversion complète, la limite vaut (1+r)/(1−r)=1,98/0,02=99. Une différence de seulement 2 % entre stocks de fonctions plafonne donc la longueur même si les fonctions limitantes réagissent presque toutes. Le ratio r concerne les quantités de groupes fonctionnels réactifs, pas simplement les masses de deux monomères ni leur pureté analytique totale. Une impureté monofonctionnelle peut arrêter des chaînes et nécessite un autre bilan. Le modèle suppose égalité de réactivité, absence de cyclisation et bifonctionnalité ; un réseau ramifié ne suit pas cette expression linéaire."),
    exercise("60. Une distribution n’est pas une chaîne unique", "PC — prolongement statistique", "polymeres",
        "On fournit la distribution en nombre xn=(1−p)p^(n−1), n≥1, d’un modèle idéal équilibré à p=0,80. Vérifier sa normalisation, donner Xn=1/(1−p) et la dispersité Đ=1+p, puis estimer Xw. Quelle fraction en nombre possède au moins 10 unités ? Une forte moyenne garantit-elle des chaînes toutes longues ?",
        "La série géométrique donne Σxn=(1−p)/(1−p)=1. Xn=1/(1−0,80)=5 ; Đ=1+0,80=1,80, donc Xw=ĐXn=9 si masses de motifs identiques et effets d’extrémité négligés. La fraction en nombre n≥10 est Σn≥10(1−p)p^(n−1)=p⁹=0,80⁹≈13,42 %. Les moyennes pondèrent différemment les chaînes : Xw accorde davantage de poids aux longues. Une distribution large peut contenir beaucoup de petites molécules même avec une moyenne importante, donc un matériau ne se décrit pas par « une chaîne de longueur Xn ». Ces formules résultent d’une polymérisation par étapes idéale équilibrée, pas de toute croissance radicalaire ni d’un mélange cyclisé ou ramifié."),
]


